      data: project.files.map((f) => ({
        projectId: id,
        path: f.path,
        content: f.content,
        published: true,
      })),
    }),
    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
  ]);

  return Response.json({ url: `https://${project.slug}.${SITES_BASE}` });
}

