      const name = window.prompt("What should we call this site?", "My site");
      if (name === null) return;
      const { project } = await api<{ project: { id: string } }>("/api/projects", {
        method: "POST",
        body: JSON.stringify({ name }),
      });
      router.push(`/projects/${project.id}`);
    } finally {
      setLoading(false);
