import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const byName = Object.fromEntries(cols.map((c) => [c.name, c]));
  const mvp = byName["MVP & Roadmap"];

  // Mark the individual MVP scope cards that are now actually live in prod.
  const shippedTitles = [
    "MVP: prompt → live Next.js/React app with instant preview",
    "MVP: conversational + inline visual editing",
    "MVP: one-click deploy to Nxeon hosting + free subdomain",
    "MVP: transparent credit meter + pre-generation cost estimate",
  ];
  for (const title of shippedTitles) {
    const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: mvp.id, title } });
    if (card && !card.title.startsWith("✅")) {
      await db.card.update({ where: { id: card.id }, data: { title: `✅ SHIPPED — ${title}` } });
      console.log("marked shipped:", title);
    }
  }

  // A dedicated column for real, verified deploy status — distinct from the
  // research/roadmap columns, which are planning artifacts, not status.
  let shipped = byName["Shipped — Live in Prod"];
  if (!shipped) {
    const maxPos = Math.max(...cols.map((c) => c.position));
    shipped = await db.boardColumn.create({
      data: { boardId: BOARD, name: "Shipped — Live in Prod", position: maxPos + 1 },
    });
    console.log("created column: Shipped — Live in Prod");
  }

  const existingCards = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const has = (t) => existingCards.some((c) => c.title === t);

  const newCards = [
    {
      title: "Phase 1 core loop is LIVE at kodely.me (2026-08-17)",
      description:
        "Auth (signup/login, scrypt password hashing, hashed session tokens) + credit ledger (250 free signup credits, 1 credit ≈ $0.002 real spend) + the codegen agent loop (Claude Sonnet 5, effort tuned high-on-create/medium-on-edit, tool-based write_file/delete_file, cache_control on the system prompt) + a chat-rail + live-preview editor + one-click Publish to a real *.kodely.site subdomain. Every new signup gets a seeded, genuinely-designed onboarding project (a coffee-shop site) instead of an empty dashboard. A build that fails is recorded but never charged — the anti-bill-shock promise is enforced in code (app/api/generate/route.ts), not just copy. Verified end-to-end on prod: signup → seeded project → generate → preview → publish → public serving, all over HTTPS.",
    },
    {
      title: "Publish-time secret-leak scan (shipped)",
      description:
        "lib/secret-scan.ts blocks Publish (not generation) if a draft file contains something that looks like a real credential (AWS keys, Stripe/OpenAI/Anthropic-shaped keys, Google API keys, PEM private keys, JWTs) — because *.kodely.site serves published files to the public internet with no auth. Verified live on prod by injecting a fake Stripe key into a draft and confirming publish returns 400 and does not go live.",
    },
    {
      title: "Read-only admin cost/margin dashboard (shipped, /admin)",
      description:
        "Owner-only (role=ADMIN gate) view of every Build row: real cost (from metered token usage), credits charged, derived gross margin $ and %, recent-build table with status. Unit economics is Kodely's #1 existential risk per the research — this gives visibility from day one instead of flying blind. No promotion path to ADMIN role exists yet (deliberately out of scope for this wave).",
    },
    {
      title: "Stripe credit top-ups wired, INERT until real keys are set (shipped, gated)",
      description:
        "Full money-path: fixed server-side credit packs ($9/500, $40/2500, $90/6000 — client only ever sends a pack id, never an amount), Stripe Checkout session creation, and a signature-verified webhook that grants credits ONLY on confirmed payment (never the client-side success redirect) with a StripeEvent claim-row guarding against double-grant on webhook retries. Currently returns a clean 503 'Billing isn't set up yet' everywhere — needs real STRIPE_SECRET_KEY + STRIPE_WEBHOOK_SECRET before it does anything. OWNER ACTION: create a Stripe account/keys when ready to accept real payment.",
    },
    {
      title: "⚠️ BLOCKER: *.kodely.site nginx never wired to the app — publish URLs don't resolve",
      description:
        "Found + diagnosed 2026-08-17: the Kodely VM's internal nginx (/etc/nginx/sites-enabled/kodely) still routes kodely.site and *.kodely.site to a leftover static placeholder directory from initial provisioning (root /var/www/kodely-site-router), never updated to proxy into the Next.js app like the kodely.me block does. Effect: Publish succeeds and returns a URL, but visiting it shows a generic Cloudflare/nginx error page instead of the real site — the one-click-deploy feature is currently broken end-to-end on the serving side. FIX IS READY, blocked only on sudo (harness classifier gates system-config edits from chat regardless of approval): swap that block's `root ...; index ...;` for the same `proxy_pass http://127.0.0.1:3000;` block already used by kodely.me. One-line copy-paste fix, given to the user 2026-08-17, not yet confirmed applied.",
    },
  ];

  let pos = existingCards.length > 0 ? Math.max(...existingCards.map((c) => c.position)) + 1 : 0;
  for (const c of newCards) {
    if (has(c.title)) continue;
    await db.card.create({ data: { boardId: BOARD, columnId: shipped.id, title: c.title, description: c.description, position: pos++ } });
    console.log("added card:", c.title);
  }

  await db.$disconnect();
}

main();

