import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const has = (t) => existing.some((c) => c.title === t);
  let pos = existing.length > 0 ? Math.max(...existing.map((c) => c.position)) + 1 : 0;

  const newCards = [
    {
      title: "Generate/publish rate limits + admin-promotion script (shipped)",
      description:
        "lib/rate-limit.ts caps generation at 20/user/hour and NEW publishes at 15/user/day — coarse abuse gates against runaway clients and spam-subdomain farming (NOT content moderation, which is a separate harder problem, not built). scripts/promote-admin.mjs is a CLI-only owner script to promote a user to ADMIN (no HTTP endpoint — that would be a privilege-escalation hole). Both verified live over HTTPS on prod: seeded 20 fake builds for a test user, confirmed the 21st generate call returns 429. Cleaned up test data after.",
    },
    {
      title: "Ops lesson: local↔VM package-lock.json desync silently broke a deploy",
      description:
        "2026-08-17: a stale LOCAL copy of package-lock.json (missing the stripe entry, since npm install had only ever been run on the VM) got rsynced over the VM's correct lockfile and committed, corrupting the repo's lockfile. deploy.sh's `npm ci` then failed on every subsequent deploy — but the deploy script's own guard kept the OLD build serving and STILL reported 'active' + healthy, silently masking that staging/prod were running stale code for one deploy cycle. Caught by checking .next/BUILD_ID's mtime against the deploy timestamp, not by trusting the healthcheck. Fixed by regenerating the lockfile ON THE VM (source of truth) and pulling it back down locally. Lesson for future waves: always verify BUILD_ID freshness after a deploy, don't trust 'active + healthy' alone — it only proves the PROCESS is up, not that it's running the NEW code.",
    },
  ];

  for (const c of newCards) {
    if (has(c.title)) continue;
    await db.card.create({ data: { boardId: BOARD, columnId: shipped.id, title: c.title, description: c.description, position: pos++ } });
    console.log("added:", c.title);
  }

  await db.$disconnect();
}

main();

