import { useRef, useState } from "react";
import Link from "next/link";

type Message = { role: string; content: string };
type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };

type Props = {
  projectId: string;
  projectName: string;
  slug: string;
  published: boolean;
