import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");
  const mvp = cols.find((c) => c.name === "MVP & Roadmap");

  // Retract the earlier overclaim, then correctly mark it shipped now that
  // click-to-edit... wait, click-to-edit still isn't built. Split the claim:
  // conversational editing is shipped, inline visual (click-to-edit) is not.
  const oldTitle = "✅ SHIPPED — MVP: conversational + inline visual editing";
  const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: mvp.id, title: oldTitle } });
  if (card) {
    await db.card.update({
      where: { id: card.id },
      data: {
        title: "🟡 PARTIAL — MVP: conversational + inline visual editing",
        description:
          (card.description ?? "") +
          "\n\n[2026-08-17 correction] Chat-based conversational editing IS shipped and live. Click-to-edit INLINE VISUAL editing (clicking an element in the preview to tweak it directly) is NOT built — this was incorrectly marked fully shipped earlier the same day. Still open.",
      },
    });
    console.log("corrected overclaim on:", oldTitle);
  }

  // Resolve the nginx blocker card — it's fixed now.
  const nginxCard = await db.card.findFirst({
    where: { boardId: BOARD, columnId: shipped.id, title: { startsWith: "⚠️ BLOCKER: *.kodely.site" } },
  });
  if (nginxCard) {
    await db.card.update({
      where: { id: nginxCard.id },
      data: {
        title: "✅ RESOLVED — *.kodely.site nginx fix applied (2026-08-17)",
        description:
          nginxCard.description +
          "\n\n[RESOLVED 2026-08-17] Fix applied and verified: published a fresh project on prod, confirmed the *.kodely.site URL serves the real generated site (HTTP 200, correct content) instead of the old placeholder/error page.",
      },
    });
    console.log("resolved nginx blocker card");
  }

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const has = (t) => existing.some((c) => c.title === t);
  let pos = existing.length > 0 ? Math.max(...existing.map((c) => c.position)) + 1 : 0;

  const newCards = [
    {
      title: "Checkpoints/rollback + code view (shipped)",
      description:
        "Every successful build snapshots the full draft file tree onto Build.filesSnapshot (JSON). New History panel in the editor lists past builds; Restore reverts the draft to that snapshot for free (no generation cost). New Code tab shows the current file tree read-only with per-file copy-to-clipboard. Verified end-to-end on prod: generated twice with different hero headings, confirmed restoring the first checkpoint reverted the live preview exactly. This closes the 'inline visual editing' board overclaim's checkpoint/export half — click-to-edit itself is still not built (see the corrected MVP card).",
    },
  ];
  for (const c of newCards) {
    if (has(c.title)) continue;
    await db.card.create({ data: { boardId: BOARD, columnId: shipped.id, title: c.title, description: c.description, position: pos++ } });
    console.log("added:", c.title);
  }

  await db.$disconnect();
}

main();

