  "package.json": JSON.stringify(
    {
      name: "kodely-site",
      private: true,
      version: "0.0.0",
      type: "module",
      scripts: { build: "vite build" },
      dependencies: {
        react: "^19.2.8",
        "react-dom": "^19.2.8",
