1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { scanForSecrets } from "@/lib/secret-scan";
4	import { checkPublishRateLimit } from "@/lib/rate-limit";
5	
6	export const dynamic = "force-dynamic";
7	
8	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
9	
10	// Publishing snapshots the draft tree onto the published tree. Deliberately
11	// NOT deploying to real Nxeon hosting infra in Phase 1 — that provisioner is
12	// still gated (see the Nxeon shared-hosting security review), so *.kodely.site
13	// is served straight out of this app from the published rows.
14	//
15	// The *.kodely.site wildcard's nginx block only routes to the PROD app
16	// (port 3000) — there is no separate wildcard for staging. A project
17	// published from staging would otherwise return a *.kodely.site URL that
18	// resolves through prod's app against prod's database, where the slug
19	// doesn't exist. Deriving the mode from the request's own Host header (never
20	// touches DNS, nginx, or .env) means staging always gets a URL that resolves
21	// against itself.
22	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
23	  const user = await requireUser().catch(() => null);
24	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
25	  const { id } = await params;
26	
27	  const project = await db.project.findFirst({
28	    where: { id, userId: user.id },
29	    include: { files: { where: { published: false } } },
30	  });
31	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
32	  if (project.files.length === 0) {
33	    return Response.json({ error: "Nothing to publish yet — generate a site first." }, { status: 400 });
34	  }
35	
36	  // Only gate genuinely new subdomains — republishing an already-live project
37	  // isn't the spam-farming vector this protects against.
38	  if (!project.publishedAt) {
39	    const rateLimit = await checkPublishRateLimit(user.id);
40	    if (!rateLimit.allowed) {
41	      return Response.json(
42	        { error: "You've published a lot of new sites today — try again tomorrow." },
43	        { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
44	      );
45	    }
46	  }
47	
48	  const leaks = scanForSecrets(project.files.map((f) => ({ path: f.path, content: f.content })));
49	  if (leaks.length > 0) {
50	    const { path, kind } = leaks[0];
51	    return Response.json(
52	      { error: `Publishing blocked: found what looks like a real secret in ${path} (${kind}). Remove it and try again.` },
53	      { status: 400 },
54	    );
55	  }
56	
57	  await db.$transaction([
58	    db.projectFile.deleteMany({ where: { projectId: id, published: true } }),
59	    db.projectFile.createMany({
60	      data: project.files.map((f) => ({
61	        projectId: id,
62	        path: f.path,
63	        content: f.content,
64	        published: true,
65	      })),
66	    }),
67	    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
68	  ]);
69	
70	  const host = req.headers.get("host") ?? "";
71	  const url = host.includes("staging")
72	    ? `https://${host}/api/site/${project.slug}`
73	    : `https://${project.slug}.${SITES_BASE}`;
74	
75	  return Response.json({ url });
76	}
