import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const has = (t) => existing.some((c) => c.title === t);
  let pos = existing.length > 0 ? Math.max(...existing.map((c) => c.position)) + 1 : 0;

  const newCards = [
    {
      title: "React stack rework: real Vite+React+TS+Tailwind output (shipped)",
      description:
        "Replaced static HTML generation entirely. Every project now starts from a real foundation (lib/foundation.ts: Vite 8 + React 19 + Tailwind v4 + TypeScript + hand-built UI primitives), the agent edits real .tsx components, and a bounded server-side build step (lib/build-site.ts, vite build against ONE pre-installed locked dependency tree, never npm install per generation) compiles them into the static output that's actually served. ProjectFile gained a kind column (source/build) to separate the two. Includes a self-repair loop: a failed build gets one repair attempt with the error fed back to the agent before giving up (still uncharged if it never succeeds). Two real infra bugs found and fixed while shipping this: staging AND prod .env were both missing ANTHROPIC_API_KEY (never actually verified with a real generation against the true domains before), and nginx's default proxy timeout was too short for the generate+build cycle (fixed: proxy_read_timeout 300s + proxy_buffering off on both app blocks). Verified end-to-end on real prod over HTTPS: signup → pre-built preview → real generation (14-17 real component files) → checkpoint restore → publish → public serving.",
    },
    {
      title: "Real pricing bug fixed: builds were charged 1 credit regardless of cost (shipped)",
      description:
        "costMicros() had a double unit-conversion bug flooring every charge to the 1-credit minimum — a build that actually cost ~$0.22-0.34 was being charged $0.002. Fixed; SIGNUP_GRANT raised 250->750 credits to match real costs (covers ~1 build + 2-3 edits). Also fixed a client-disconnect crash (SSE 'Controller is already closed') that could leave builds stuck RUNNING or wrongly uncharge/overcharge — now cleanly aborts the Anthropic request and resolves the build state either way.",
    },
    {
      title: "Real marketing homepage + pricing page (shipped) — first marketing-site work",
      description:
        "kodely.me finally has a real homepage (locked 'Kodely Luxe' aesthetic: Geist, near-monochrome with the brand gradient spent sparingly, one real hero object — a browser-frame mockup, not skeleton blocks — extreme whitespace) and a real /pricing page pulling the ACTUAL Stripe credit packs and free-credit grant from lib/stripe.ts / lib/credits.ts (can't drift from what's actually charged). Verified visually via Playwright screenshots in light, dark, and mobile before shipping. This is the very first item shipped from the ~283-card Marketing/SEO/GTM/Brand backlog — the other ~280 cards (SEO content pages, comparison pages, full brand site) are still unbuilt; this covers only the two pages every visitor needs first (homepage, pricing).",
    },
  ];
  for (const c of newCards) {
    if (has(c.title)) continue;
    await db.card.create({ data: { boardId: BOARD, columnId: shipped.id, title: c.title, description: c.description, position: pos++ } });
    console.log("added:", c.title);
  }

  await db.$disconnect();
}

main();

