import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  // Mark the 14 source briefs as shipped, with a note where content was
  // honestly reframed away from the literal brief (backend claims that
  // aren't true yet).
  const shippedTitles = {
    "Kodely vs Rocket.new": null,
    "Kodely vs Lovable": null,
    "Build a booking / appointment website with AI": null,
    "Build a online store (ecommerce) with AI": null,
    "AI website builder for dentists": null,
    "AI website builder for chiropractors": null,
    "How to build a website with AI": null,
    "How to build a SaaS app with AI": "Reframed as a SaaS LANDING PAGE guide -- Kodely has no backend generation, the literal brief overclaimed.",
    "What is an AI website builder?": null,
    "What is vibe coding?": null,
    "Free AI website builder": "Corrected: removed the brief's false 'you keep the code'/'first month hosting free' claims (neither is true).",
    "AI SaaS builder": "Reframed as an AI SaaS LANDING PAGE builder -- same backend-overclaim correction as the SaaS app guide.",
    "Kodely for founders": null,
    "Kodely for agencies": "Corrected: brief referenced a non-existent 'Agency plan' -- content is honest that pricing is the same for everyone.",
  };

  for (const [title, note] of Object.entries(shippedTitles)) {
    const cols2 = await db.boardColumn.findMany({ where: { boardId: BOARD, name: { startsWith: "SEO" } } });
    const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: { in: cols2.map((c) => c.id) }, title } });
    if (card && !card.title.startsWith("✅")) {
      await db.card.update({
        where: { id: card.id },
        data: {
          title: `✅ SHIPPED — ${title}`,
          description: (card.description ?? "") + (note ? `\n\n[2026-08-17] ${note}` : "\n\n[2026-08-17] Live at kodely.me/blog."),
        },
      });
      console.log("marked shipped:", title);
    } else {
      console.log("not found or already marked:", title);
    }
  }

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const pos = Math.max(...existing.map((c) => c.position)) + 1;

  await db.card.create({
    data: {
      boardId: BOARD,
      columnId: shipped.id,
      position: pos,
      title: "SEO content: first batch of 14/251 pages live (shipped)",
      description:
        "New BlogPost model + /blog + /blog/[slug] routes (shared MarketingNav/Footer extracted for reuse). First real content batch: 14 pages across all 7 SEO columns (2 each: Comparisons, Use-Cases, Industries, Guides, Glossary, Feature, Personas), written by 14 parallel agents against a strict factual-constraints brief so nothing overclaims vs. what Kodely actually ships today. Several original board briefs contained STALE pre-pivot claims (backend/database/payments 'included', 'first month hosting free', 'you keep the code', a fictional 'Agency plan') -- these were corrected or honestly reframed rather than copied verbatim; see individual card notes. Verified via Playwright screenshots (blog index + 2 articles) before shipping, then re-verified live on kodely.me/blog over real HTTPS. Ops note: extracting agent JSON output from raw transcripts hit two malformed-JSON edge cases (a literal unescaped newline, and unescaped straight quotes inside prose) -- both recovered by hand rather than losing the content; future batches should ask agents to avoid straight quotes in body text or should validate/repair JSON before treating an agent's output as final. 237 briefs remain across the 7 SEO columns -- this is the first wave of an ongoing effort, not close to done.",
    },
  });
  console.log("added summary card");
  await db.$disconnect();
}

main();

import { PrismaClient } from "@prisma/client";
import { readFileSync } from "node:fs";

const db = new PrismaClient();
const posts = JSON.parse(readFileSync("./seo-batch1.json", "utf8"));

for (const p of posts) {
  await db.blogPost.upsert({
    where: { slug: p.slug },
    create: {
      slug: p.slug,
      title: p.title,
      metaDescription: p.metaDescription,
      category: p.category,
      targetKeyword: p.targetKeyword,
      bodyHtml: p.bodyHtml,
    },
    update: {
      title: p.title,
      metaDescription: p.metaDescription,
      category: p.category,
      targetKeyword: p.targetKeyword,
      bodyHtml: p.bodyHtml,
    },
  });
  console.log("inserted:", p.slug);
}

console.log(`\n${posts.length} posts upserted.`);
await db.$disconnect();

