"use client";

import { motion } from "framer-motion";

/**
 * A single blurred brand-gradient shape used as ambient depth behind a hero
 * or CTA. Fades/scales in once on mount — no looping color shimmer (that
 * read as "cheap" in earlier design passes; the gradient itself is static).
 */
export function GradientOrb({ className = "" }: { className?: string }) {
  return (
    <motion.div
      aria-hidden
      className={`pointer-events-none absolute rounded-full blur-[90px] ${className}`}
      style={{ background: "var(--brand-gradient)" }}
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 1.8, ease: [0.16, 1, 0.3, 1] }}
    />
  );
}

