import { chromium } from "playwright";

const shots = [
  { name: "home-light", url: "http://127.0.0.1:3099/", theme: "light", viewport: { width: 1440, height: 1000 } },
  { name: "home-dark", url: "http://127.0.0.1:3099/", theme: "dark", viewport: { width: 1440, height: 1000 } },
  { name: "home-mobile", url: "http://127.0.0.1:3099/", theme: "light", viewport: { width: 390, height: 844 } },
  { name: "pricing-light", url: "http://127.0.0.1:3099/pricing", theme: "light", viewport: { width: 1440, height: 1000 } },
  { name: "blog-light", url: "http://127.0.0.1:3099/blog", theme: "light", viewport: { width: 1440, height: 1000 } },
  { name: "blog-dark", url: "http://127.0.0.1:3099/blog", theme: "dark", viewport: { width: 1440, height: 1000 } },
  { name: "article-light", url: "http://127.0.0.1:3099/blog/what-is-vibe-coding", theme: "light", viewport: { width: 1440, height: 1200 } },
  { name: "article-mobile", url: "http://127.0.0.1:3099/blog/what-is-vibe-coding", theme: "light", viewport: { width: 390, height: 900 } },
];

const browser = await chromium.launch();
for (const s of shots) {
  const ctx = await browser.newContext({ viewport: s.viewport, colorScheme: s.theme });
  const page = await ctx.newPage();
  await page.goto(s.url, { waitUntil: "networkidle" });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/${s.name}.png`, fullPage: true });
  await ctx.close();
  console.log("shot:", s.name);
}
await browser.close();

