  await page.goto(s.url, { waitUntil: "networkidle" });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/${s.name}.png`, fullPage: true });
  await ctx.close();
  console.log("shot:", s.name);
}
await browser.close();

