359	<script>
360	(function(){
361	"use strict";
362	var reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
363	var clamp=function(v,a,b){return v<a?a:v>b?b:v;};
364	
365	/* theme */
366	var root=document.documentElement,tgl=document.getElementById("tgl");
367	var SUN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4.2"/><path d="M12 2v2M12 20v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M2 12h2M20 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/></svg>';
368	var MOON='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A8.5 8.5 0 1 1 11.2 3a6.6 6.6 0 0 0 9.8 9.8z"/></svg>';
369	function isDark(){var t=root.getAttribute("data-theme");if(t)return t==="dark";return matchMedia("(prefers-color-scheme: dark)").matches;}
370	function paint(){tgl.innerHTML=isDark()?SUN:MOON;}
371	try{var sv=localStorage.getItem("kodely-theme");if(sv)root.setAttribute("data-theme",sv);}catch(e){}
372	paint();
373	tgl.addEventListener("click",function(){var n=isDark()?"light":"dark";root.setAttribute("data-theme",n);try{localStorage.setItem("kodely-theme",n);}catch(e){}paint();});
374	
375	/* loader */
376	var loader=document.getElementById("loader");
377	requestAnimationFrame(function(){loader.classList.add("run");});
378	setTimeout(function(){loader.classList.add("done");boot();},reduce?150:1000);
379	
380	/* nav */
381	var nav=document.getElementById("nav");
382	addEventListener("scroll",function(){nav.classList.toggle("stuck",scrollY>30);},{passive:true});
383	
384	/* reveal */
385	var rio=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add("in");rio.unobserve(e.target);}});},{threshold:.14,rootMargin:"0px 0px -8% 0px"});
386	document.querySelectorAll(".rv").forEach(function(el){rio.observe(el);});
387	
388	function boot(){
389	  /* hero site assembles once, gently loops */
390	  var site=document.getElementById("heroSite");
391	  var els=[].slice.call(site.querySelectorAll(".s-el"));
392	  function build(){els.forEach(function(el,i){setTimeout(function(){el.classList.add("in");el.style.opacity="1";el.style.transform="none";},reduce?0:220+i*160);});}
393	  // use built class approach: stagger via inline since .site.built handles it
394	  site.classList.add("built");
395	  els.forEach(function(el,i){el.style.transitionDelay=(reduce?0:0.18+i*0.13)+"s";});
396	  requestAnimationFrame(function(){els.forEach(function(el){el.classList.add("in");});});
397	  if(!reduce){
398	    setInterval(function(){
399	      els.forEach(function(el){el.style.transitionDelay="0s";el.classList.remove("in");el.style.opacity="0";el.style.transform="translateY(12px)";});
400	      setTimeout(function(){els.forEach(function(el,i){el.style.transitionDelay=(0.05+i*0.11)+"s";el.classList.add("in");el.style.opacity="";el.style.transform="";});},700);
401	    },7000);
402	  }
403	}
404	
405	/* statement pinned — smooth, few elements */
406	(function(){
407	  var sec=document.querySelector(".state");if(!sec)return;
408	  var words=[].slice.call(sec.querySelectorAll(".word"));
409	  var ticking=false;
410	  function update(){
411	    ticking=false;
412	    var r=sec.getBoundingClientRect();var total=sec.offsetHeight-innerHeight;var p=clamp(-r.top/(total||1),0,1);
413	    words.forEach(function(w,i){
414	      var seg=1/words.length;var local=clamp((p-i*seg)/seg,0,1);
415	      var vis=Math.sin(local*Math.PI);
416	      w.style.opacity=vis.toFixed(3);
417	      w.style.transform="translateY("+((1-vis)*(local<.5?36:-36)).toFixed(1)+"px) scale("+(.9+vis*.1).toFixed(3)+")";
418	      w.style.filter="blur("+((1-vis)*6).toFixed(1)+"px)";
419	    });
420	  }
421	  addEventListener("scroll",function(){if(!ticking){ticking=true;requestAnimationFrame(update);}},{passive:true});
422	  addEventListener("resize",update);update();
423	})();
424	
425	/* speed counter */
426	(function(){
427	  var num=document.getElementById("speedNum"),prog=document.getElementById("speedProg");
428	  var steps=["Designing…","Writing content…","Building components…","Wiring the database…","Deploying…","Published ✦"];
429	  var started=false;
430	  new IntersectionObserver(function(es){if(es[0].isIntersecting&&!started){started=true;go();}},{threshold:.5}).observe(document.getElementById("speed"));
431	  function go(){
432	    var t0=performance.now(),dur=1700,target=47;
433	    (function tick(now){var p=clamp((now-t0)/dur,0,1);var e=1-Math.pow(1-p,3);num.textContent=Math.round(e*target);if(p<1)requestAnimationFrame(tick);else num.textContent=target;})(performance.now());
434	    steps.forEach(function(s,k){setTimeout(function(){prog.textContent=s;},k*300);});
435	  }
436	})();
437	
438	/* stat counter */
439	(function(){
440	  var el=document.getElementById("statNum");if(!el)return;var started=false;
441	  new IntersectionObserver(function(es){if(es[0].isIntersecting&&!started){started=true;var t0=performance.now();(function tick(now){var p=clamp((now-t0)/1700,0,1);var e=1-Math.pow(1-p,3);el.textContent=Math.round(e*10000).toLocaleString();if(p<1)requestAnimationFrame(tick);else el.textContent="10,000";})(performance.now());}},{threshold:.6}).observe(el);
442	})();
443	
444	/* subtle magnetic on primary buttons only */
445	if(matchMedia("(pointer:fine)").matches&&!reduce){
446	  document.querySelectorAll(".mag").forEach(function(el){
447	    el.addEventListener("mousemove",function(e){var r=el.getBoundingClientRect();el.style.transform="translate("+((e.clientX-(r.left+r.width/2))*.18)+"px,"+((e.clientY-(r.top+r.height/2))*.28)+"px)";});
448	    el.addEventListener("mouseleave",function(){el.style.transform="";});
449	  });
450	}
451	})();
452	</script>
