:root {
  --background: #ffffff;
  --foreground: #171717;
  /* Brand gradient — spent deliberately (wordmark, CTAs, one highlight),
     never as a page-wide wash. Locked 2026-08-16. */
  --brand-coral: #ff6a3d;
  --brand-magenta: #ec2e88;
  --brand-purple: #9b2fd6;
  --brand-gradient: linear-gradient(100deg, var(--brand-coral), var(--brand-magenta), var(--brand-purple));
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
}

.brand-gradient-text {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   instead of a Tailwind typography plugin dependency, matching the same
   near-monochrome + generous-whitespace system as the rest of the site. */
.article-body h2 {
  margin-top: 2.75rem;
  margin-bottom: 1rem;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.article-body h3 {
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
  font-weight: 600;
}
.article-body p {
  margin-bottom: 1.25rem;
  line-height: 1.75;
  color: var(--foreground);
}
.article-body ul,
.article-body ol {
  margin: 1.25rem 0 1.25rem 1.25rem;
  line-height: 1.75;
}
.article-body ul {
  list-style: disc;
}
.article-body ol {
  list-style: decimal;
}
.article-body li {
  margin-bottom: 0.4rem;
}
.article-body a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--foreground) 30%, transparent);
}
.article-body strong {
  font-weight: 600;
}
.article-body code {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.875em;
  background: color-mix(in srgb, var(--foreground) 6%, transparent);
  padding: 0.15em 0.4em;
  border-radius: 0.3em;
}
.article-body table {
  width: 100%;
  margin: 1.5rem 0;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.article-body th,
.article-body td {
  border: 1px solid color-mix(in srgb, var(--foreground) 12%, transparent);
  padding: 0.6rem 0.9rem;
  text-align: left;
}
.article-body th {
  font-weight: 600;
  background: color-mix(in srgb, var(--foreground) 4%, transparent);
}
.article-body blockquote {
  border-left: 3px solid color-mix(in srgb, var(--foreground) 20%, transparent);
  padding-left: 1.1rem;
  margin: 1.5rem 0;
  color: color-mix(in srgb, var(--foreground) 70%, transparent);
}

