          cx="27"
          cy="11"
          r="4.4"
          fill={`url(#${gradId})`}
        />
        <motion.rect
          variants={shapeVariants}
          transition={{ duration: 0.5, ease: [0.2, 0.9, 0.2, 1] }}
          x="18"
          y="17"
          width="15"
          height="7"
          rx="3.5"
          fill={`url(#${gradId})`}
          transform="rotate(-38 25.5 20.5)"
        />
        <motion.rect
          variants={shapeVariants}
          transition={{ duration: 0.5, ease: [0.2, 0.9, 0.2, 1] }}
          x="18"
          y="17"
          width="16"
          height="7"
          rx="3.5"
          fill={`url(#${gradId})`}
          transform="rotate(40 25.5 24)"
        />
        <motion.rect
          variants={shapeVariants}
          transition={{ duration: 0.5, ease: [0.2, 0.9, 0.2, 1] }}
          x="24"
          y="30"
          width="7"
          height="7"
          rx="2.3"
          fill={`url(#${gradId})`}
          transform="rotate(45 27.5 33.5)"
        />
      </motion.g>
    </svg>
  );
}

export function Logo({ className = "", markSize = 24 }: { className?: string; markSize?: number }) {
  return (
    <span className={`inline-flex items-center gap-2 font-semibold tracking-tight ${className}`}>
      <Mark size={markSize} />
      <span className="brand-gradient-text">kodely</span>
    </span>
  );
}

