import { chromium } from "playwright";

const browser = await chromium.launch();

// Verify the pinned scroll statement at 3 distinct scroll offsets, viewport-only
// (fullPage screenshots misrender sticky-positioned scroll-linked sections).
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  const el = await page.$("section:has(> div.sticky)");
  const box = await el.boundingBox();
  const offsets = [0.16, 0.5, 0.84];
  for (const [i, frac] of offsets.entries()) {
    await page.evaluate((y) => window.scrollTo(0, y), box.y + box.height * frac);
    await page.waitForTimeout(400);
    await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/pinned-${i}.png` });
  }
  await ctx.close();
}

// Nav close-up (top of page, not scrolled) + scrolled/stuck state
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 300 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  await page.waitForTimeout(400);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/nav-top.png` });
  await page.evaluate(() => window.scrollTo(0, 800));
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/nav-stuck.png` });
  await ctx.close();
}

// Theme toggle click -> dark mode applied live
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  await page.waitForTimeout(400);
  await page.click('button[aria-label="Toggle theme"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/theme-toggle-clicked.png` });
  await ctx.close();
}

await browser.close();
console.log("done");

