const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });

const total = await page.evaluate(() => document.body.scrollHeight);
console.log("total scrollHeight:", total);

// Sweep from just after the hero through past the pinned section in ~250px
// steps, screenshotting the viewport at each step, to find real behavior.
const start = 900;
const end = 4200;
const step = 250;
let n = 0;
for (let y = start; y <= end; y += step) {
  await page.evaluate((yy) => window.scrollTo(0, yy), y);
  await page.waitForTimeout(150);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/sweep-${String(n).padStart(2, "0")}-y${y}.png` });
  n++;
}

await browser.close();
console.log("done", n, "shots");

