import { chromium } from "playwright";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });

const info = await page.evaluate(() => {
  const sections = [...document.querySelectorAll("section")];
  const pinned = sections.find((s) => s.querySelector(":scope > div.sticky"));
  if (!pinned) return { error: "pinned section not found", sectionCount: sections.length };
  const rect = pinned.getBoundingClientRect();
  const words = [...pinned.querySelectorAll(".sticky > div")];
  return {
    scrollY: window.scrollY,
    pinnedTop: rect.top + window.scrollY,
    pinnedHeight: rect.height,
    wordCount: words.length,
    wordStyles: words.map((w) => {
      const cs = getComputedStyle(w);
      return { opacity: cs.opacity, transform: cs.transform, filter: cs.filter, text: w.textContent };
    }),
  };
});
console.log(JSON.stringify(info, null, 2));

// Now scroll through and sample opacity of each word every 200px
const sectionTop = info.pinnedTop;
const sectionHeight = info.pinnedHeight;
for (let y = sectionTop - 200; y < sectionTop + sectionHeight + 200; y += 200) {
  await page.evaluate((yy) => window.scrollTo(0, yy), y);
  await page.waitForTimeout(80);
  const sample = await page.evaluate(() => {
    const pinned = [...document.querySelectorAll("section")].find((s) => s.querySelector(":scope > div.sticky"));
    const words = [...pinned.querySelectorAll(".sticky > div")];
    return words.map((w) => Number(getComputedStyle(w).opacity).toFixed(2));
  });
  console.log("y=", y, "opacities=", sample);
}

await browser.close();

