import { chromium } from "playwright";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });

// Scroll gradually via real wheel gestures (not instant jumps) so Chromium
// compositing/paint keeps pace, then settle and shoot.
async function scrollToAndShoot(target, name) {
  let y = await page.evaluate(() => window.scrollY);
  while (y < target) {
    await page.mouse.wheel(0, 120);
    y = await page.evaluate(() => window.scrollY);
  }
  await page.waitForTimeout(500);
  // force a tiny nudge to trigger a fresh paint
  await page.mouse.wheel(0, 1);
  await page.waitForTimeout(400);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/${name}.png` });
}

await scrollToAndShoot(1727, "wheel-word0");
await scrollToAndShoot(2327, "wheel-word1");
await scrollToAndShoot(2927, "wheel-word2");

await browser.close();
console.log("done");

