import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const pos = Math.max(...existing.map((c) => c.position)) + 1;

  await db.card.create({
    data: {
      boardId: BOARD,
      columnId: shipped.id,
      position: pos,
      title: "Marketing site redesigned to match approved Kodely Luxe reference (shipped)",
      description:
        "User flagged the shipped homepage 'looks nothing like the original mockup' (scratchpad/kodely.html, the approved Kodely Luxe reference). Root cause: the earlier marketing-site pass was a simplified rebuild that drifted -- flat, no motion, wrong gradient hex, plain nav, no hero object motion. Ported the real reference closely: ambient two-blob 'aura' background (static color, present on every marketing page), floating glass pill nav that compacts to a blurred capsule on scroll, K-mark SVG logo that assembles once on mount, manual light/dark theme toggle (class-based .dark on <html>, no-flash inline script, persisted to localStorage -- previously only had OS-preference dark mode, no manual control), hero mini-site demo that assembles in and gently re-loops every 8s (framer-motion), scroll-pinned 'Describe it. / Generate it. / Ship it.' cross-fade section, alternating 2-column feature blocks with custom visuals (code snippet, shield, live-URL pill), magnetic cursor-follow CTA buttons, gradient-border 'most popular' pricing card, redesigned blog index (card grid) and article page (reading time, category pill, scroll progress bar, related-reading, end-of-article CTA). Added framer-motion + lucide-react as new deps. IMPORTANT: the reference mockup itself contains STALE/aspirational copy from before this session's product pivot -- 'export to GitHub', 'you own the code', 'database, auth & payments included', 'custom domain', 'first month hosting free', a 3-tier Free/Pro/Agency subscription pricing model, and a fabricated '10,000+ sites built' stat. None of that was copied verbatim -- kept the real credit-based pricing (SIGNUP_GRANT/CREDIT_PACKS pulled from code) and rewrote feature copy to only claim what's actually true today (real React code visible in the Code tab, publish-time secret scanning, one-click *.kodely.site with HTTPS). Hit and fixed two real bugs while building: framer-motion's target-based useScroll() never re-measured against a Next.js-hydrated ref (silently frozen at initial values) -- replaced with a manual scroll-listener-driven motion value, confirmed working via direct computed-style inspection; and overflow-hidden on the page root wrapper silently disabled position:sticky for the pinned section (a classic CSS gotcha) -- removed it since Aura already clips itself. Verified via Playwright (light/dark/mobile screenshots, live scroll-through of the pinned section, live theme-toggle click) before shipping, then re-verified on the real kodely.me domain post-deploy. Deployed staging (cecd3b8) -> verified -> prod (cecd3b8), both fresh BUILD_ID, both re-checked over real HTTPS.",
    },
  });
  console.log("added card");
  await db.$disconnect();
}

main();

