async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const shippedTitles = {
    "Kodely vs Bolt.new": null,
    "Kodely vs v0": null,
    "Build a portfolio website with AI": null,
    "Build a SaaS landing page with AI": "Reframed to be explicit this builds the marketing/landing page, not the SaaS product itself -- Kodely has no backend/auth/payments generation.",
    "AI website builder for law firms": "Corrected: brief implied a real booking/payments backend -- content is honest that Kodely builds the marketing site with a contact-form UI, not a scheduling/payment system.",
    "AI website builder for accountants": "Corrected: same booking/payments correction as law firms.",
    "How to build a website without code": null,
    "How to write a great AI website prompt": null,
    "What is a no-code app builder?": null,
    "AI website builder vs traditional website builder": null,
    "AI website builder for beginners": "Corrected: removed the brief's false 'you keep the code' and 'first month of hosting free' claims (neither is true).",
    "AI website generator from a description": "Corrected: same 'you keep the code' / 'first month of hosting free' correction.",
    "Kodely for freelancers": "Corrected: dropped the brief's fake testimonial slot and the non-existent 'Agency plan' link -- no testimonials exist yet, pricing is the same for everyone.",
    "Kodely for small businesses": "Corrected: same testimonial/Agency-plan correction as freelancers.",
  };

  for (const [title, note] of Object.entries(shippedTitles)) {
    const cols2 = await db.boardColumn.findMany({ where: { boardId: BOARD, name: { startsWith: "SEO" } } });
    const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: { in: cols2.map((c) => c.id) }, title } });
    if (card && !card.title.startsWith("✅")) {
      await db.card.update({
        where: { id: card.id },
        data: {
          title: `✅ SHIPPED — ${title}`,
          description: (card.description ?? "") + (note ? `\n\n[2026-08-17] ${note}` : "\n\n[2026-08-17] Live at kodely.me/blog."),
        },
      });
      console.log("marked shipped:", title);
    } else {
      console.log("not found or already marked:", title);
    }
  }

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const pos = Math.max(...existing.map((c) => c.position)) + 1;

  await db.card.create({
    data: {
      boardId: BOARD,
      columnId: shipped.id,
      position: pos,
      title: "SEO content: second batch of 14 pages live (28/251 total)",
      description:
        "Second SEO content wave, same discipline as batch 1: 14 pages (2 each across all 7 columns), written by 14 parallel agents against the standing factual-constraints brief, extracted from raw transcripts (not notification-displayed text), validated/repaired as JSON, screenshot-verified against the newly-redesigned marketing site before shipping. All 14 deliberately picked to be honestly buildable without heavy reframing -- the Guides and Feature & Integrations columns still contain ~40 cards each describing specific third-party backend integrations (Stripe, Supabase, Postgres, Clerk, Airtable, Zapier, S3, GitHub export, custom domains, Nxeon hosting) that Kodely genuinely cannot do yet; those were skipped this wave rather than reframed, since a page about 'how to add a Postgres database to your Kodely site' would be describing a roadmap item as if it were real, regardless of how it's worded. Flagging this as a real backlog composition issue, not just a content-writing task -- worth a decision on whether those ~80 cards get deprioritized, rewritten as roadmap-honest 'coming soon' pieces, or dropped once and reconciled against the board. Deployed straight to both staging and prod DBs (no code changes this wave, content-only) and verified live over real HTTPS on kodely.me. 28/251 briefs now live; 223 remain.",
    },
  });
  console.log("added summary card");
  await db.$disconnect();
}

main();

