import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const shippedTitles = {
    "Kodely vs Webflow": null,
    "Kodely vs Wix": null,
    "Build a personal website with AI": null,
    "Build a agency website with AI": "Corrected: removed the brief's false 'database and payments included' meta description claim.",
    "AI website builder for restaurants": "Corrected: brief implied real booking/payment/ordering -- content is honest that Kodely builds the marketing site with a reservation-request contact form UI, not a live booking system, and points to the real booking-website guide for that need.",
    "AI website builder for photographers": "Corrected: same booking correction, plus an honest note that the gallery ships with placeholder images -- Kodely doesn't handle real photo upload/hosting yet.",
    "How to make a landing page that converts": null,
    "How to make your AI-generated site secure": "Written carefully to avoid fabricating a security-vulnerability statistic -- framed the industry concern generally and accurately instead of inventing a number.",
    "Frontend vs backend, explained simply": null,
    "Do you own the code from AI website builders?": "A candid piece on Kodely's real current gap (no full project export yet, view/copy only) -- used deliberately to build trust rather than oversell 'you own the code.'",
    "AI website builder with no credit card required": "Corrected: removed the brief's false 'you keep the code' and 'first month of hosting free' claims.",
    "AI website builder with transparent pricing": "Corrected: same false-claim removal as no-credit-card page.",
    "Kodely for solopreneurs": "Corrected: dropped the brief's fake testimonial slot and non-existent 'Agency plan' link.",
    "Kodely for nonprofits": "Corrected: same testimonial/Agency-plan correction, plus an explicit, honest note that Kodely builds a Donate CTA but does not process real donations -- that still requires connecting a real payment processor separately.",
  };

  for (const [title, note] of Object.entries(shippedTitles)) {
    const cols2 = await db.boardColumn.findMany({ where: { boardId: BOARD, name: { startsWith: "SEO" } } });
    const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: { in: cols2.map((c) => c.id) }, title } });
    if (card && !card.title.startsWith("✅")) {
      await db.card.update({
        where: { id: card.id },
        data: {
          title: `✅ SHIPPED — ${title}`,
          description: (card.description ?? "") + (note ? `\n\n[2026-08-17] ${note}` : "\n\n[2026-08-17] Live at kodely.me/blog."),
        },
      });
      console.log("marked shipped:", title);
    } else {
      console.log("not found or already marked:", title);
    }
  }

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const pos = Math.max(...existing.map((c) => c.position)) + 1;

  await db.card.create({
    data: {
      boardId: BOARD,
      columnId: shipped.id,
      position: pos,
      title: "SEO content: third batch of 14 pages live (42/251 total)",
      description:
        "Third SEO content wave, same discipline as batches 1-2: 14 pages (2 each across all 7 columns), 14 parallel agents against the standing factual-constraints brief, extracted from raw transcripts, validated as JSON (all 14 parsed clean this time -- the extraction script now locates the first '{' by default rather than trying a fenced-code-block regex first, which fixed the batch-2 prose-wrapping failure mode for good), category strings checked against the live DB before insert (all matched, no repeat of the batch-2 Use-Cases/Use Cases mismatch), screenshot-verified against the redesigned marketing site, deployed to both staging and prod DBs (content-only, no code changes), verified live over real HTTPS. Picks continued avoiding the Guides/Feature&Integrations false-premise trap flagged after batch 2 -- this wave leaned into Glossary as a strong honest-content column (educational pages like 'frontend vs backend' and 'do you own the code from AI builders' that build trust by being candid about real gaps rather than needing any reframing) and picked Comparisons/Industries/Personas/Use-Cases entries that only needed the same light corrections as prior batches (dropping fake testimonials, the non-existent 'Agency plan', 'first month hosting free', and being explicit that booking/donation forms are UI-only with no backend behind them). 42/251 briefs now live; 209 remain, and the ~80-card Guides/Feature&Integrations backend-integration question from the batch-2 note is still open and unaddressed.",
    },
  });
  console.log("added summary card");
  await db.$disconnect();
}

main();

