import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const BOARD = "cmsw33mv20000hlokqv7gze6u";

async function main() {
  const cols = await db.boardColumn.findMany({ where: { boardId: BOARD }, orderBy: { position: "asc" } });
  const shipped = cols.find((c) => c.name === "Shipped — Live in Prod");

  const shippedTitles = {
    "Kodely vs WordPress": null,
    "Kodely vs Squarespace": null,
    "Build a link-in-bio page with AI": "Corrected: removed the false 'database and payments included' claim; added honest note that Kodely has no click-analytics (a real link-in-bio-tool feature it lacks).",
    "Build a podcast website with AI": "Corrected: made explicit Kodely builds the site, not podcast/RSS hosting infrastructure.",
    "AI website builder for hair salons": "Corrected: 'bookings and payments included' -> booking inquiry contact-form UI only, same pattern as law firms/accountants.",
    "AI website builder for interior designers": "Corrected: same booking correction, plus honest note that gallery images are placeholders.",
    "How to build a portfolio that gets you hired": null,
    "How to launch a startup landing page": "Added an honest note that the email-signup form is UI-only -- Kodely has no backend to store submissions, needs a real capture tool wired in separately.",
    "What is an API? (plain-English guide)": null,
    "Build a website by chatting with AI": "Corrected: removed 'you keep the code' / 'first month of hosting free' claims.",
    "AI website builder with hosting included": "Corrected: same false-claim removal; clarified 'hosting included' means the kodely.site subdomain, not a custom domain.",
    "Kodely for developers (fast prototyping)": "Corrected: dropped fake testimonial + non-existent Agency plan; explicit that there's no export-to-your-repo yet, which matters specifically to this audience.",
    "Kodely for creators": "Corrected: same testimonial/Agency-plan removal; honest that there's no click-analytics for a link-hub use case.",
    "Static vs dynamic websites explained": "Technically precise piece -- explains Kodely's output is static-served (compiled Vite/React bundle), not dynamically server-rendered, and why (no backend to do per-request generation).",
  };

  for (const [title, note] of Object.entries(shippedTitles)) {
    const cols2 = await db.boardColumn.findMany({ where: { boardId: BOARD, name: { startsWith: "SEO" } } });
    const card = await db.card.findFirst({ where: { boardId: BOARD, columnId: { in: cols2.map((c) => c.id) }, title } });
    if (card && !card.title.startsWith("✅")) {
      await db.card.update({
        where: { id: card.id },
        data: {
          title: `✅ SHIPPED — ${title}`,
          description: (card.description ?? "") + (note ? `\n\n[2026-08-17] ${note}` : "\n\n[2026-08-17] Live at kodely.me/blog."),
        },
      });
      console.log("marked shipped:", title);
    } else {
      console.log("not found or already marked:", title);
    }
  }

  const existing = await db.card.findMany({ where: { boardId: BOARD, columnId: shipped.id } });
  const pos = Math.max(...existing.map((c) => c.position)) + 1;

  await db.card.create({
    data: {
      boardId: BOARD,
      columnId: shipped.id,
      position: pos,
      title: "SEO content: fourth batch of 14 pages live (56/251 total)",
      description:
        "Fourth SEO content wave, same discipline as batches 1-3: 14 pages (2 each across all 7 columns), 14 parallel agents, extracted from raw transcripts, category-checked against the live DB before insert (all matched). One JSON parse failure this wave (unescaped straight quotes inside an FAQ heading, 'the \"simple\" or \"unchangeable\" site?') -- repaired by hand same as before; agents still occasionally do this despite explicit instructions to avoid straight quotes, so manual JSON repair remains a standing part of this pipeline, not a solved problem. Mid-wave the user also asked for three homepage/site fixes (handled in a separate commit, 84a8f79): a 'companies we work with' carousel request was corrected to a 'what people build with Kodely' showcase carousel instead, since Kodely has no real named customers and fabricating logos would be misrepresentation -- user agreed after being asked directly; the hero mockup's blank placeholder product swatches got icon illustrations; and the login/signup pages (previously unstyled leftovers) were redesigned to match the site, which also surfaced and fixed a real bug -- signup copy hardcoded '250 free credits' when the actual SIGNUP_GRANT is 750. Deployed straight to both staging and prod DBs and verified live over real HTTPS. 56/251 briefs now live; 195 remain. The ~80-card Guides/Feature&Integrations backend-integration question (flagged after batch 2) is still open.",
    },
  });
  console.log("added summary card");
  await db.$disconnect();
}

main();

