6	type Message = { role: string; content: string };
7	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
8	
9	type Props = {
10	  projectId: string;
11	  projectName: string;
12	  slug: string;
13	  published: boolean;
14	  initialFiles: Record<string, string>;
15	  initialMessages: Message[];
16	  initialBalance: number;
17	};
18	
19	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
20	
21	// Mirrors the publish route's own Host-based derivation (see the comment
22	// there) so the header's "live site" link always matches what publish
23	// actually returned, on staging or prod, without hardcoding either.
24	function liveSiteUrl(slug: string): string {
25	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
26	  const host = window.location.host;
27	  return host.includes("staging")
28	    ? `${window.location.origin}/api/site/${slug}`
29	    : `https://${slug}.${SITES_BASE}`;
30	}
31	
32	export default function Editor(props: Props) {
33	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
34	  const [files, setFiles] = useState(props.initialFiles);
35	  const [prompt, setPrompt] = useState("");
36	  const [busy, setBusy] = useState(false);
37	  const [status, setStatus] = useState<string | null>(null);
38	  const [error, setError] = useState<string | null>(null);
39	  const [balance, setBalance] = useState(props.initialBalance);
40	  const [previewNonce, setPreviewNonce] = useState(0);
41	  const [published, setPublished] = useState(props.published);
42	  const [publishing, setPublishing] = useState(false);
43	  const [view, setView] = useState<"preview" | "code" | "history">("preview");
44	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
45	  const [restoring, setRestoring] = useState<string | null>(null);
46	  const [activeFile, setActiveFile] = useState<string | null>(null);
47	  const streamingReply = useRef("");
48	
49	  async function openHistory() {
50	    setView("history");
51	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
52	    const body = await res.json();
53	    setBuilds(body.builds ?? []);
54	  }
55	
56	  async function restore(buildId: string) {
57	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
58	    setRestoring(buildId);
59	    setError(null);
60	    try {
61	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
62	        method: "POST",
63	      });
64	      const body = await res.json();
65	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
66	      const res2 = await fetch(`/api/projects/${props.projectId}`);
67	      const body2 = await res2.json();
68	      const nextFiles: Record<string, string> = Object.fromEntries(
69	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
70	      );
71	      setFiles(nextFiles);
72	      setPreviewNonce((n) => n + 1);
73	      setView("preview");
74	    } catch (err) {
75	      setError(err instanceof Error ? err.message : "Restore failed.");
76	    } finally {
77	      setRestoring(null);
78	    }
79	  }
80	
81	  // The foundation means source files are never empty — "first build" means
82	  // no chat history yet, matching the same signal the generate route uses.
83	  const isFirstBuild = messages.length === 0;
84	
85	  async function send() {
86	    const text = prompt.trim();
87	    if (!text || busy) return;
88	    if (balance <= 0) {
89	      setError("You're out of credits. Top up to keep building.");
90	      return;
91	    }
92	
93	    setBusy(true);
94	    setError(null);
95	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
96	    setMessages((m) => [...m, { role: "user", content: text }]);
97	    setPrompt("");
98	    streamingReply.current = "";
99	
100	    try {
101	      const res = await fetch("/api/generate", {
102	        method: "POST",
103	        headers: { "Content-Type": "application/json" },
104	        body: JSON.stringify({ projectId: props.projectId, prompt: text }),
105	      });
106	
107	      if (!res.ok || !res.body) {
108	        const body = await res.json().catch(() => ({}));
109	        throw new Error(body?.error ?? "The build failed to start.");
110	      }
111	
112	      const reader = res.body.getReader();
113	      const decoder = new TextDecoder();
114	      let buffer = "";
115	      let touchedFiles = false;
116	
117	      while (true) {
118	        const { done, value } = await reader.read();
119	        if (done) break;
120	        buffer += decoder.decode(value, { stream: true });
121	
122	        const parts = buffer.split("\n\n");
123	        buffer = parts.pop() ?? "";
124	
125	        for (const part of parts) {
126	          if (!part.startsWith("data: ")) continue;
127	          const event = JSON.parse(part.slice(6));
128	
129	          if (event.type === "text") {
130	            streamingReply.current += event.text;
131	          } else if (event.type === "file") {
132	            touchedFiles = true;
133	            setStatus(`${event.action === "write" ? "Writing" : "Removing"} ${event.path}`);
134	          } else if (event.type === "done") {
135	            setBalance(event.remaining);
136	            setStatus(null);
137	          } else if (event.type === "error") {
138	            throw new Error(event.message);
139	          }
140	        }
141	      }
142	
143	      if (streamingReply.current.trim()) {
144	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
145	      }
146	      if (touchedFiles) {
147	        const res2 = await fetch(`/api/projects/${props.projectId}`);
148	        const body = await res2.json();
149	        const nextFiles: Record<string, string> = Object.fromEntries(
150	          (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
151	        );
152	        setFiles(nextFiles);
153	        setPreviewNonce((n) => n + 1);
154	      }
155	    } catch (err) {
156	      setError(err instanceof Error ? err.message : "Something went wrong.");
157	    } finally {
158	      setBusy(false);
159	      setStatus(null);
160	    }
161	  }
162	
163	  async function publish() {
164	    setPublishing(true);
165	    setError(null);
166	    try {
167	      const res = await fetch(`/api/projects/${props.projectId}/publish`, { method: "POST" });
168	      const body = await res.json();
