190	            <button
191	              onClick={() => setView("preview")}
192	              className={`rounded-md px-2 py-1 ${view === "preview" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
193	            >
194	              Preview
195	            </button>
196	            <button
197	              onClick={() => {
198	                setView("code");
199	                setActiveFile((f) => f ?? Object.keys(files)[0] ?? null);
200	              }}
201	              className={`rounded-md px-2 py-1 ${view === "code" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
202	              disabled={isFirstBuild}
203	            >
204	              Code
205	            </button>
206	            <button
207	              onClick={openHistory}
208	              className={`rounded-md px-2 py-1 ${view === "history" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
209	              disabled={isFirstBuild}
210	            >
211	              History
212	            </button>
213	          </div>
