import { chromium } from "playwright";

const browser = await chromium.launch();

// 1. Hero screenshot, light + dark, unfocused
for (const [name, dark] of [["hero-light", false], ["hero-dark", true]]) {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: dark ? "dark" : "light" });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/prompt-${name}.png` });
  await ctx.close();
}

// 2. Focused + typed state, light
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  await page.click("textarea");
  await page.fill("textarea", "A landing page for my dog walking business called Pawsitive Steps");
  await page.waitForTimeout(400);
  await page.screenshot({ path: "/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/prompt-focused.png" });
  await ctx.close();
}

// 3. Full end-to-end: type prompt, submit -> should land on signup with preview shown
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3099/", { waitUntil: "networkidle" });
  await page.fill("textarea", "A landing page for my dog walking business called Pawsitive Steps");
  await page.click('button[aria-label="Start building"]');
  await page.waitForURL("**/signup", { timeout: 5000 });
  await page.waitForTimeout(500);
  await page.screenshot({ path: "/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/prompt-signup-preview.png" });

  // Verify sessionStorage actually carries it
  const stored = await page.evaluate(() => sessionStorage.getItem("kodely:pending_prompt"));
  console.log("sessionStorage pending prompt:", JSON.stringify(stored));
  await ctx.close();
}

await browser.close();
console.log("done");

