16	export function PromptHero() {
17	  const router = useRouter();
18	  const reduced = useReducedMotion();
19	  const [value, setValue] = useState("");
20	  const [focused, setFocused] = useState(false);
21	
22	  function submit() {
23	    const text = value.trim();
24	    if (!text) return;
25	    try {
26	      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
27	    } catch {}
28	    router.push("/signup");
29	  }
30	
31	  return (
32	    <div className="relative mx-auto w-full max-w-2xl">
33	      {/* The glow — a static-color brand gradient, breathing slowly. Not a
34	          color-cycling shimmer (that pattern was rejected earlier in this
35	          project) — just a calm pulse in scale/opacity, like Gemini's
36	          composer glow. */}
37	      <motion.div
38	        aria-hidden
39	        className="pointer-events-none absolute -inset-8 -z-10 rounded-[2.5rem] blur-2xl"
40	        style={{ background: "var(--brand-gradient)" }}
41	        initial={{ opacity: 0.35, scale: 0.96 }}
42	        animate={
43	          reduced
44	            ? { opacity: 0.45, scale: 1 }
45	            : { opacity: [0.35, 0.55, 0.35], scale: [0.96, 1, 0.96] }
46	        }
47	        transition={{ duration: 5, repeat: reduced ? 0 : Infinity, ease: "easeInOut" }}
48	      />
49	      <motion.div
50	        aria-hidden
51	        className="pointer-events-none absolute -inset-8 -z-10 rounded-[2.5rem] blur-2xl"
52	        style={{ background: "var(--brand-gradient)" }}
53	        animate={reduced ? { opacity: 0.15 } : { opacity: [0.15, 0.3, 0.15] }}
54	        transition={{ duration: 5, repeat: reduced ? 0 : Infinity, ease: "easeInOut", delay: 1.4 }}
55	      />
56	
57	      {/* The glass composer itself. */}
58	      <div
59	        className={`relative overflow-hidden rounded-[1.75rem] border transition-all duration-300 ${
60	          focused
61	            ? "border-white/60 shadow-[0_20px_60px_-16px_var(--glow)] dark:border-white/20"
62	            : "border-white/40 shadow-[0_12px_40px_-16px_var(--glow)] dark:border-white/10"
63	        } bg-white/55 backdrop-blur-2xl dark:bg-white/[0.06]`}
64	        style={{ boxShadow: focused ? undefined : "var(--sh-s)" }}
65	      >
66	        {/* Glass sheen — a soft highlight along the top edge. */}
67	        <div
68	          className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/80 to-transparent dark:via-white/30"
69	          aria-hidden
70	        />
71	        <textarea
72	          value={value}
73	          onChange={(e) => setValue(e.target.value)}
74	          onFocus={() => setFocused(true)}
75	          onBlur={() => setFocused(false)}
76	          onKeyDown={(e) => {
77	            if (e.key === "Enter" && !e.shiftKey) {
78	              e.preventDefault();
79	              submit();
80	            }
81	          }}
82	          rows={2}
83	          placeholder="Describe the site you want to build…"
84	          className="w-full resize-none bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 dark:text-white dark:placeholder:text-neutral-400"
