"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { ArrowUp } from "lucide-react";
import { motion, useReducedMotion } from "framer-motion";
import { PENDING_PROMPT_KEY } from "@/lib/pending-prompt";

const SUGGESTIONS = [
  "A portfolio site for a freelance photographer",
  "A landing page for my SaaS product",
  "A website for a neighborhood coffee shop",
  "A booking page for my consulting practice",
];

export function PromptHero() {
  const router = useRouter();
  const reduced = useReducedMotion();
  const [value, setValue] = useState("");
  const [focused, setFocused] = useState(false);

  function submit() {
    const text = value.trim();
    if (!text) return;
    try {
      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
    } catch {}
    router.push("/signup");
  }

  return (
    <div className="relative mx-auto w-full max-w-2xl">
      {/* The glow — a static-color brand gradient, breathing slowly. Not a
          color-cycling shimmer (that pattern was rejected earlier in this
          project) — just a calm pulse in scale/opacity, like Gemini's
          composer glow. */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute -inset-8 -z-10 rounded-[2.5rem] blur-2xl"
        style={{ background: "var(--brand-gradient)" }}
        initial={{ opacity: 0.35, scale: 0.96 }}
        animate={
          reduced
            ? { opacity: 0.45, scale: 1 }
            : { opacity: [0.35, 0.55, 0.35], scale: [0.96, 1, 0.96] }
        }
        transition={{ duration: 5, repeat: reduced ? 0 : Infinity, ease: "easeInOut" }}
      />
      <motion.div
        aria-hidden
        className="pointer-events-none absolute -inset-8 -z-10 rounded-[2.5rem] blur-2xl"
        style={{ background: "var(--brand-gradient)" }}
        animate={reduced ? { opacity: 0.15 } : { opacity: [0.15, 0.3, 0.15] }}
        transition={{ duration: 5, repeat: reduced ? 0 : Infinity, ease: "easeInOut", delay: 1.4 }}
      />

      {/* The glass composer itself. */}
      <div
        className={`relative overflow-hidden rounded-[1.75rem] border transition-all duration-300 ${
          focused
            ? "border-white/60 shadow-[0_20px_60px_-16px_var(--glow)] dark:border-white/20"
            : "border-white/40 shadow-[0_12px_40px_-16px_var(--glow)] dark:border-white/10"
        } bg-white/55 backdrop-blur-2xl dark:bg-white/[0.06]`}
        style={{ boxShadow: focused ? undefined : "var(--sh-s)" }}
      >
        {/* Glass sheen — a soft highlight along the top edge. */}
        <div
          className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/80 to-transparent dark:via-white/30"
          aria-hidden
        />
        <textarea
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              submit();
            }
          }}
          rows={2}
          placeholder="Describe the site you want to build…"
          className="w-full resize-none bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 dark:text-white dark:placeholder:text-neutral-400"
        />
        <motion.button
          type="button"
          onClick={submit}
          disabled={!value.trim()}
          aria-label="Start building"
          whileHover={value.trim() ? { scale: 1.06 } : undefined}
          whileTap={value.trim() ? { scale: 0.94 } : undefined}
          className="absolute bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full text-white shadow-sm transition-opacity disabled:opacity-30"
          style={{ background: "var(--brand-gradient)" }}
        >
          <ArrowUp size={16} strokeWidth={2.5} />
        </motion.button>
      </div>

      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
        {SUGGESTIONS.map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => setValue(s)}
            className="rounded-full border border-neutral-200/70 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 backdrop-blur-md transition-colors hover:border-neutral-300 hover:text-neutral-900 dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white"
          >
            {s}
          </button>
        ))}
      </div>
    </div>
  );
}

