import { chromium } from "playwright";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto("https://kodely.me/", { waitUntil: "networkidle" });

const times = [0.3, 1, 2, 3, 5, 7, 10];
let last = 0;
for (const t of times) {
  await page.waitForTimeout((t - last) * 1000);
  last = t;
  await page.screenshot({
    path: `/tmp/claude-0/-root/312233c7-67c0-4f44-899d-b3d8dee31ae1/scratchpad/shots/glow-t${t}s.png`,
    clip: { x: 300, y: 500, width: 840, height: 350 },
  });
  // Read the actual computed opacity/style of the glow layers directly.
  const info = await page.evaluate(() => {
    const textarea = document.querySelector("textarea");
    if (!textarea) return null;
    // walk up to the PromptHero root (the div with class containing "max-w-2xl")
    let root = textarea;
    while (root && !(root.className && String(root.className).includes("max-w-2xl"))) {
      root = root.parentElement;
    }
    if (!root) return { error: "root not found" };
    const glowDivs = [...root.children].filter((c) => c.getAttribute("aria-hidden") === "true");
    return glowDivs.map((d) => {
      const cs = getComputedStyle(d);
      return { opacity: cs.opacity, transform: cs.transform, display: cs.display, visibility: cs.visibility };
    });
  });
  console.log(`t=${t}s`, JSON.stringify(info));
}

await browser.close();
console.log("done");

