@import "tailwindcss";

/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
   override the OS preference — Tailwind's dark: classes elsewhere in the
   app are unaffected in shape, only in what triggers them. */
@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #ffffff;
  --foreground: #171717;

  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
     (scratchpad/kodely.html) so the shipped site and the approved design
     don't drift again. */
  --ink-2: #605b66;
  --faint: #a49fad;
  --line: rgba(11, 10, 13, 0.09);
  --line-2: rgba(11, 10, 13, 0.045);
  --panel: #ffffff;
  --accent: #e01b6e;
  --glow: rgba(247, 37, 112, 0.13);
  --glow-2: rgba(163, 61, 255, 0.12);
  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);

  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --background: #0a0a0a;
    --foreground: #ededed;
    --ink-2: #a8a1b0;
    --faint: #5f5869;
    --line: rgba(246, 243, 247, 0.1);
    --line-2: rgba(246, 243, 247, 0.05);
    --panel: #100e15;
    --accent: #ff5c97;
    --glow: rgba(255, 76, 139, 0.22);
    --glow-2: rgba(180, 114, 255, 0.2);
    --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
    --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
    --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
  }
}

:root.dark {
  --background: #0a0a0a;
  --foreground: #ededed;
  --ink-2: #a8a1b0;
  --faint: #5f5869;
  --line: rgba(246, 243, 247, 0.1);
  --line-2: rgba(246, 243, 247, 0.05);
  --panel: #100e15;
  --accent: #ff5c97;
  --glow: rgba(255, 76, 139, 0.22);
  --glow-2: rgba(180, 114, 255, 0.2);
  --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
  --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
  --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
}

.brand-gradient-text {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Ambient background — one very slow, very soft light behind every
   marketing page. Fixed, never scrolls, never shifts color — the motion
   budget is spent on foreground elements, not this. */
.aura {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.aura b {
  position: absolute;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.6;
}
.aura .a1 {
  width: 52vw;
  height: 52vw;
  left: -8vw;
  top: -14vw;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.aura .a2 {
  width: 46vw;
  height: 46vw;
  right: -10vw;
  bottom: -4vw;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   instead of a Tailwind typography plugin dependency, matching the same
   near-monochrome + generous-whitespace system as the rest of the site. */
.article-body h2 {
  margin-top: 2.75rem;
  margin-bottom: 1rem;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.article-body h3 {
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
  font-weight: 600;
}
.article-body p {
  margin-bottom: 1.25rem;
  line-height: 1.75;
  color: var(--foreground);
}
.article-body ul,
.article-body ol {
  margin: 1.25rem 0 1.25rem 1.25rem;
  line-height: 1.75;
}
.article-body ul {
  list-style: disc;
}
.article-body ol {
  list-style: decimal;
}
.article-body li {
  margin-bottom: 0.4rem;
}
.article-body a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--foreground) 30%, transparent);
}
.article-body strong {
  font-weight: 600;
}
.article-body code {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.875em;
  background: color-mix(in srgb, var(--foreground) 6%, transparent);
  padding: 0.15em 0.4em;
  border-radius: 0.3em;
}
.article-body table {
  width: 100%;
  margin: 1.5rem 0;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.article-body th,
.article-body td {
  border: 1px solid color-mix(in srgb, var(--foreground) 12%, transparent);
  padding: 0.6rem 0.9rem;
  text-align: left;
}
.article-body th {
  font-weight: 600;
  background: color-mix(in srgb, var(--foreground) 4%, transparent);
}
.article-body blockquote {
  border-left: 3px solid color-mix(in srgb, var(--foreground) 20%, transparent);
  padding-left: 1.1rem;
  margin: 1.5rem 0;
  color: color-mix(in srgb, var(--foreground) 70%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.2s !important;
  }
}

import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { db } from "@/lib/db";
import { MarketingNav } from "@/components/marketing/MarketingNav";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { Aura } from "@/components/marketing/Aura";
import { Reveal, RevealGroup, RevealItem } from "@/components/marketing/Reveal";
import { MotionLift } from "@/components/marketing/FloatCard";

export const dynamic = "force-dynamic";

export default async function BlogIndexPage() {
  const posts = await db.blogPost.findMany({
    orderBy: { publishedAt: "desc" },
    select: { slug: true, title: true, metaDescription: true, category: true },
  });

  const byCategory = new Map<string, typeof posts>();
  for (const post of posts) {
    const list = byCategory.get(post.category) ?? [];
    list.push(post);
    byCategory.set(post.category, list);
  }

  return (
    <div className="relative min-h-screen bg-white text-neutral-900 dark:bg-neutral-950 dark:text-neutral-50">
      <Aura />
      <MarketingNav />

      <section className="relative">
        <div className="relative mx-auto max-w-4xl px-6 pb-8 pt-40 text-center sm:pt-52">
          <Reveal>
            <h1 className="text-4xl font-semibold tracking-tight sm:text-5xl">
              The <span className="brand-gradient-text">Kodely</span> blog
            </h1>
          </Reveal>
          <Reveal delay={0.08}>
            <p className="mx-auto mt-5 max-w-xl text-lg text-neutral-600 dark:text-neutral-400">
              Guides, comparisons, and ideas for building a real site with AI.
            </p>
          </Reveal>
        </div>
      </section>

      <section className="relative mx-auto max-w-5xl px-6 py-10">
        {posts.length === 0 ? (
          <p className="text-center text-sm text-neutral-500 dark:text-neutral-500">
            Nothing published yet — check back soon.
          </p>
        ) : (
          Array.from(byCategory.entries()).map(([category, items]) => (
            <div key={category} className="mb-16">
              <Reveal>
                <h2 className="mb-5 flex items-center gap-2 text-sm font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400">
                  <span
                    className="h-1.5 w-1.5 rounded-full"
                    style={{ background: "var(--brand-gradient)" }}
                    aria-hidden
                  />
                  {category}
                </h2>
              </Reveal>
              <RevealGroup className="grid gap-5 sm:grid-cols-2" stagger={0.06}>
                {items.map((post) => (
                  <RevealItem key={post.slug}>
                    <MotionLift lift={4} className="h-full">
                      <Link
                        href={`/blog/${post.slug}`}
                        className="group flex h-full flex-col rounded-2xl border border-neutral-200 p-6 transition-shadow hover:shadow-lg dark:border-neutral-800"
                      >
                        <h3 className="text-lg font-semibold leading-snug tracking-tight">{post.title}</h3>
                        <p className="mt-2 flex-1 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
                          {post.metaDescription}
                        </p>
                        <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-neutral-900 dark:text-white">
                          Read article
                          <ArrowRight size={14} className="transition-transform group-hover:translate-x-1" />
                        </span>
                      </Link>
                    </MotionLift>
                  </RevealItem>
                ))}
              </RevealGroup>
            </div>
          ))
        )}
      </section>

      <MarketingFooter />
    </div>
  );
}

