1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import { api, ApiError } from "@/lib/api";
7	import { SIGNUP_GRANT } from "@/lib/credits";
8	import { PENDING_PROMPT_KEY, destinationAfterAuth } from "@/lib/pending-prompt";
9	import { Reveal } from "@/components/marketing/Reveal";
10	import { MotionLift } from "@/components/marketing/FloatCard";
11	
12	const inputClass =
13	  "w-full rounded-lg border border-neutral-200 bg-white px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-neutral-400 focus:border-neutral-400 dark:border-neutral-800 dark:bg-neutral-950 dark:placeholder:text-neutral-600 dark:focus:border-neutral-600";
14	
15	export default function SignupPage() {
16	  const router = useRouter();
17	  const [email, setEmail] = useState("");
18	  const [password, setPassword] = useState("");
19	  const [error, setError] = useState<string | null>(null);
20	  const [loading, setLoading] = useState(false);
21	  const [pendingPrompt, setPendingPrompt] = useState<string | null>(null);
22	
23	  useEffect(() => {
24	    try {
25	      setPendingPrompt(sessionStorage.getItem(PENDING_PROMPT_KEY));
26	    } catch {}
27	  }, []);
28	
29	  async function onSubmit(e: React.FormEvent) {
30	    e.preventDefault();
31	    setError(null);
32	    setLoading(true);
33	    try {
34	      await api("/api/auth/signup", { method: "POST", body: JSON.stringify({ email, password }) });
35	      const dest = await destinationAfterAuth();
36	      router.push(dest);
37	      router.refresh();
38	    } catch (err) {
39	      setError(err instanceof ApiError ? err.message : "Something went wrong.");
40	    } finally {
41	      setLoading(false);
42	    }
43	  }
44	
45	  return (
46	    <Reveal>
47	      <form
48	        onSubmit={onSubmit}
49	        className="space-y-5 rounded-2xl border border-neutral-200 bg-white/80 p-7 shadow-[var(--sh-s)] backdrop-blur-sm dark:border-neutral-800 dark:bg-neutral-950/80"
50	      >
51	        <div>
52	          <h1 className="text-xl font-semibold tracking-tight">
53	            Create your <span className="brand-gradient-text">account</span>
54	          </h1>
55	          <p className="mt-1 text-sm text-neutral-500 dark:text-neutral-400">
56	            {SIGNUP_GRANT} free credits, no card required — enough to build and iterate on a real site.
57	          </p>
58	        </div>
59	
60	        {pendingPrompt && (
61	          <div className="rounded-lg border border-neutral-200 bg-neutral-50 px-3.5 py-3 text-sm dark:border-neutral-800 dark:bg-neutral-900">
62	            <p className="text-xs font-medium uppercase tracking-wide text-neutral-500 dark:text-neutral-400">
63	              Picking up where you left off
64	            </p>
65	            <p className="mt-1 text-neutral-700 dark:text-neutral-300">“{pendingPrompt}”</p>
66	          </div>
67	        )}
68	
69	        <div className="space-y-3">
70	          <input
71	            type="email"
72	            required
73	            placeholder="Email"
74	            value={email}
75	            onChange={(e) => setEmail(e.target.value)}
76	            className={inputClass}
77	          />
78	          <input
79	            type="password"
80	            required
81	            minLength={8}
82	            placeholder="Password (min 8 characters)"
83	            value={password}
84	            onChange={(e) => setPassword(e.target.value)}
85	            className={inputClass}
86	          />
87	        </div>
88	
89	        {error && (
90	          <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600 dark:bg-red-950/40 dark:text-red-400">
91	            {error}
92	          </p>
93	        )}
94	
95	        <MotionLift lift={2} className="block">
96	          <button
97	            type="submit"
98	            disabled={loading}
99	            className="w-full rounded-lg px-3.5 py-2.5 text-sm font-medium text-white shadow-[0_14px_34px_-16px_var(--glow)] transition-opacity disabled:opacity-50"
100	            style={{ background: "var(--brand-gradient)" }}
101	          >
102	            {loading ? "Creating account…" : pendingPrompt ? "Create account & build it" : "Create account"}
103	          </button>
104	        </MotionLift>
105	
106	        <p className="text-center text-sm text-neutral-500 dark:text-neutral-400">
