2	import { getCurrentUser } from "@/lib/auth";
3	import { runAgent, normalizePath, type FileMap } from "@/lib/agent";
4	import { buildSite, BuildError } from "@/lib/build-site";
5	import { chargeForBuild, costMicros, creditsFor, getBalance } from "@/lib/credits";
6	import { checkGenerateRateLimit } from "@/lib/rate-limit";
7	
8	export const dynamic = "force-dynamic";
9	export const maxDuration = 300;
10	
11	function sse(event: unknown) {
12	  return `data: ${JSON.stringify(event)}\n\n`;
13	}
14	
15	// A build that fails to compile even after one repair attempt gives up — this
16	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
17	const MAX_BUILD_ATTEMPTS = 2;
18	
19	export async function POST(req: Request) {
20	  const user = await getCurrentUser();
21	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
22	
23	  const body = (await req.json().catch(() => null)) as {
24	    projectId?: string;
25	    prompt?: string;
26	  } | null;
27	  const prompt = body?.prompt?.trim();
28	  if (!body?.projectId || !prompt) {
29	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
30	  }
31	
32	  const project = await db.project.findFirst({
33	    where: { id: body.projectId, userId: user.id },
34	    include: { messages: { orderBy: { createdAt: "asc" } } },
35	  });
36	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
37	
38	  const balance = await getBalance(user.id);
39	  if (balance <= 0) {
40	    return Response.json(
41	      { error: "You're out of credits. Top up to keep building." },
42	      { status: 402 },
43	    );
44	  }
45	
46	  const rateLimit = await checkGenerateRateLimit(user.id);
47	  if (!rateLimit.allowed) {
48	    return Response.json(
49	      { error: "You're generating too fast — take a short break and try again shortly." },
50	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
51	    );
52	  }
53	
54	  // The foundation means source files are never empty — "first build" is
55	  // instead "first real customization request" for this project.
56	  const kind = project.messages.length === 0 ? "create" : "edit";
57	
58	  const build = await db.build.create({
59	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
60	  });
61	
62	  await db.message.create({
63	    data: { projectId: project.id, role: "user", content: prompt },
64	  });
65	
66	  // Aborted when the client disconnects (tab closed, network drop) — cancels
67	  // the in-flight Anthropic request instead of burning tokens for nobody.
68	  const abortController = new AbortController();
69	
70	  const encoder = new TextEncoder();
71	  const stream = new ReadableStream({
72	    async start(controller) {
73	      // A client disconnect races with our own sends: enqueue on a closed
74	      // controller throws "Controller is already closed", which used to be
75	      // caught as a generic failure and wrongly mark an otherwise-fine build
76	      // FAILED. There's nothing to do about a gone client — swallow it.
77	      const send = (event: unknown) => {
78	        try {
79	          controller.enqueue(encoder.encode(sse(event)));
80	        } catch {
81	          // client is gone
82	        }
83	      };
84	
85	      let filesWritten = 0;
86	      let succeeded = false;
87	      const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
88	      let model = "";
89	      let lastReply = "";
90	
91	      const readSourceFiles = async (): Promise<FileMap> => {
92	        const rows = await db.projectFile.findMany({
93	          where: { projectId: project.id, published: false, kind: "source" },
94	        });
95	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
96	      };
97	
98	      try {
99	        let request = prompt;
100	        let buildOutput: FileMap | null = null;
101	        let lastBuildError = "";
102	
103	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
104	          if (abortController.signal.aborted) break;
105	
106	          const generator = runAgent({
107	            history: project.messages.map((m) => ({
108	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
109	              content: m.content,
110	            })),
111	            request,
112	            files: await readSourceFiles(),
113	            kind,
114	            signal: abortController.signal,
115	            onWrite: async (path, content) => {
116	              if (!normalizePath(path)) return false;
117	              await db.projectFile.upsert({
118	                where: {
119	                  projectId_path_published_kind: {
120	                    projectId: project.id,
121	                    path,
122	                    published: false,
123	                    kind: "source",
124	                  },
125	                },
126	                create: { projectId: project.id, path, content, published: false, kind: "source" },
127	                update: { content },
128	              });
129	              filesWritten++;
130	              return true;
131	            },
132	            onDelete: async (path) => {
133	              const { count } = await db.projectFile.deleteMany({
134	                where: { projectId: project.id, path, published: false, kind: "source" },
135	              });
136	              return count > 0;
137	            },
138	          });
139	
140	          for await (const event of generator) {
141	            if (event.type === "text") {
142	              lastReply += event.text;
143	              send(event);
144	            } else if (event.type === "file") {
145	              send(event);
146	            } else if (event.type === "usage") {
147	              model = event.model;
148	              totals.inputTokens += event.inputTokens;
149	              totals.outputTokens += event.outputTokens;
150	              totals.cacheReadTokens += event.cacheReadTokens;
151	              totals.cacheWriteTokens += event.cacheWriteTokens;
152	            }
153	          }
154	
155	          if (abortController.signal.aborted) break;
156	
157	          try {
158	            buildOutput = await buildSite(await readSourceFiles());
159	            break; // compiled cleanly — done
160	          } catch (err) {
161	            lastBuildError = err instanceof BuildError ? err.message : String(err);
162	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
163	            send({ type: "status", text: "Build didn't compile — fixing it…" });
164	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
165	          }
166	        }
167	
168	        if (abortController.signal.aborted || !buildOutput) {
169	          // Loop ended without a successful build and without throwing —
170	          // only reachable via the abort path (see the `break` above).
171	        } else {
172	          succeeded = true;
173	
174	          // Replace the compiled tree with the new build output.
175	          await db.$transaction([
176	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
177	            ...(Object.keys(buildOutput).length > 0
178	              ? [
179	                  db.projectFile.createMany({
180	                    data: Object.entries(buildOutput).map(([path, content]) => ({
181	                      projectId: project.id,
182	                      path,
183	                      content,
184	                      published: false,
185	                      kind: "build",
186	                    })),
187	                  }),
188	                ]
189	              : []),
190	          ]);
191	
192	          const micros = costMicros(model, totals);
193	          const credits = creditsFor(micros);
194	          const remaining = await chargeForBuild(user.id, build.id, credits);
195	
196	          const sourceFiles = await readSourceFiles();
197	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
198	
199	          await db.build.update({
200	            where: { id: build.id },
201	            data: {
202	              status: "SUCCEEDED",
203	              model,
204	              endedAt: new Date(),
205	              inputTokens: totals.inputTokens,
206	              outputTokens: totals.outputTokens,
207	              cacheReadTokens: totals.cacheReadTokens,
208	              cacheWriteTokens: totals.cacheWriteTokens,
209	              filesWritten,
210	              costMicros: micros,
211	              creditsCharged: credits,
212	              filesSnapshot,
213	            },
214	          });
215	
216	          if (lastReply.trim()) {
217	            await db.message.create({
218	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
219	            });
220	          }
221	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
222	
223	          send({ type: "done", credits, remaining, filesWritten });
224	        }
225	
226	        if (!succeeded) {
227	          await db.build.update({
228	            where: { id: build.id },
229	            data: {
230	              status: "FAILED",
231	              endedAt: new Date(),
232	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
233	              filesWritten,
234	              creditsCharged: 0,
235	            },
236	          });
237	        }
238	      } catch (error) {
239	        // A build that fails is never charged — that is the product promise,
240	        // so the ledger is deliberately untouched on this path.
241	        const message =
242	          error instanceof Error ? error.message : "The build failed unexpectedly.";
243	        console.error("[kodely] build failed", build.id, error);
244	
245	        await db.build.update({
246	          where: { id: build.id },
247	          data: {
248	            status: "FAILED",
249	            endedAt: new Date(),
250	            error: message.slice(0, 1000),
251	            filesWritten,
252	            creditsCharged: 0,
253	          },
