351	              ) : (
352	                <ul className="space-y-2">
353	                  {builds.map((b) => (
354	                    <li
355	                      key={b.id}
356	                      className="flex items-center justify-between rounded-lg border border-black/10 px-3 py-2 dark:border-white/10"
357	                    >
358	                      <div className="min-w-0">
359	                        <div className="truncate text-sm">{b.prompt}</div>
360	                        <div className="text-xs text-black/40 dark:text-white/40">
361	                          {new Date(b.createdAt).toLocaleString()} · {b.filesWritten} file{b.filesWritten === 1 ? "" : "s"} touched
362	                        </div>
363	                      </div>
364	                      <button
