366	                        disabled={restoring === b.id}
367	                        className="ml-3 shrink-0 rounded-md border border-black/15 px-2 py-1 text-xs disabled:opacity-50 dark:border-white/15"
368	                      >
369	                        {restoring === b.id ? "Restoring…" : "Restore"}
370	                      </button>
371	                    </li>
372	                  ))}
373	                </ul>
374	              )}
375	            </div>
376	          )}
377	        </div>
378	      </div>
379	    </div>
