const DATA_URI_RE = /data:[a-zA-Z0-9+.\-/]+;base64,[A-Za-z0-9+/=]+/g;

function redact(value: string): string {
  return value.length <= 6 ? `${value}…` : `${value.slice(0, 6)}…`;
}

