async function readGlow() {
  return page.evaluate(() => {
    const textarea = document.querySelector("textarea");
    let root = textarea;
    while (root && !(root.className && String(root.className).includes("max-w-2xl"))) root = root.parentElement;
    if (!root) return null;
    const glows = [...root.children].filter(c => c.getAttribute("aria-hidden") === "true");
    return glows.map(g => getComputedStyle(g).opacity);
  });
}

for (const t of [0, 100, 200, 300, 500, 800, 1200, 2000]) {
  await page.waitForTimeout(t === 0 ? 0 : 100);
  console.log(`~t=${t}ms`, JSON.stringify(await readGlow()));
}
await browser.close();
