        height: "540px",
        background: "radial-gradient(closest-side, var(--glow), transparent)",
      }}
      initial={{ opacity: 0.7 }}
      animate={
        reduced
          ? { opacity: focused ? 0.95 : 0.8 }
          : {
              opacity: focused ? [0.75, 1, 0.75] : [0.6, 0.88, 0.6],
