1	"use client";
2	
3	import { useRouter } from "next/navigation";
4	import { useEffect, useRef, useState } from "react";
5	import { ArrowUp, Paperclip, Mic, X, Gift } from "lucide-react";
6	import { motion, useReducedMotion } from "framer-motion";
7	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
8	import { SIGNUP_GRANT } from "@/lib/credits";
9	
10	const SUGGESTIONS = [
11	  "A portfolio site for a freelance photographer",
12	  "A landing page for my SaaS product",
13	  "A website for a neighborhood coffee shop",
14	  "A booking page for my consulting practice",
15	];
16	
17	// Downscale + re-encode client-side so a phone photo doesn't blow past
18	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
19	// at it) — a reference image only needs to be legible, not full-resolution.
20	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
21	  const bitmap = await createImageBitmap(file);
22	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
23	  const w = Math.round(bitmap.width * scale);
24	  const h = Math.round(bitmap.height * scale);
25	  const canvas = document.createElement("canvas");
26	  canvas.width = w;
27	  canvas.height = h;
28	  const ctx = canvas.getContext("2d");
29	  if (!ctx) throw new Error("canvas unsupported");
30	  ctx.drawImage(bitmap, 0, 0, w, h);
31	  return canvas.toDataURL("image/jpeg", quality);
32	}
33	
34	type SpeechRecognitionLike = {
35	  continuous: boolean;
36	  interimResults: boolean;
37	  lang: string;
38	  start: () => void;
39	  stop: () => void;
40	  onresult: ((e: any) => void) | null;
41	  onend: (() => void) | null;
42	  onerror: (() => void) | null;
43	};
44	
45	function getSpeechRecognition(): (new () => SpeechRecognitionLike) | null {
46	  if (typeof window === "undefined") return null;
47	  return (window as any).SpeechRecognition ?? (window as any).webkitSpeechRecognition ?? null;
48	}
49	
50	export function PromptHero() {
51	  const router = useRouter();
52	  const reduced = useReducedMotion();
53	  const [value, setValue] = useState("");
54	  const [focused, setFocused] = useState(false);
55	  const [image, setImage] = useState<string | null>(null);
56	  const [listening, setListening] = useState(false);
57	  const [speechSupported, setSpeechSupported] = useState(false);
58	  const fileInputRef = useRef<HTMLInputElement>(null);
59	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
60	  const baseValueRef = useRef("");
61	
62	  useEffect(() => {
63	    setSpeechSupported(getSpeechRecognition() !== null);
64	  }, []);
65	
66	  function submit() {
67	    const text = value.trim();
68	    if (!text) return;
69	    try {
70	      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
71	      if (image) sessionStorage.setItem(PENDING_PROMPT_IMAGE_KEY, image);
72	      else sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
73	    } catch {}
74	    router.push("/signup");
75	  }
76	
77	  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
78	    const file = e.target.files?.[0];
79	    e.target.value = "";
80	    if (!file || !file.type.startsWith("image/")) return;
81	    try {
82	      setImage(await downscaleImage(file));
83	    } catch {}
84	  }
85	
86	  function toggleListening() {
87	    const Ctor = getSpeechRecognition();
88	    if (!Ctor) return;
89	
90	    if (listening) {
91	      recognitionRef.current?.stop();
92	      return;
93	    }
94	
95	    const rec = new Ctor();
96	    rec.continuous = true;
97	    rec.interimResults = true;
98	    rec.lang = "en-US";
99	    baseValueRef.current = value ? value.trim() + " " : "";
100	
101	    rec.onresult = (e: any) => {
102	      let transcript = "";
103	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
104	      setValue((baseValueRef.current + transcript).trimStart());
105	    };
106	    rec.onend = () => setListening(false);
107	    rec.onerror = () => setListening(false);
108	
109	    recognitionRef.current = rec;
110	    rec.start();
111	    setListening(true);
112	  }
113	
114	  useEffect(() => () => recognitionRef.current?.stop(), []);
115	
116	  return (
