1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { motion, AnimatePresence, useReducedMotion, type Variants } from "framer-motion";
5	import { Mark } from "./Logo";
6	
7	const PROMPT_TEXT = "A creative studio portfolio, bold and modern, with a project gallery";
8	
9	const PHASE_DURATIONS = { typing: 2600, building: 2400, live: 5200 } as const;
10	type Phase = "typing" | "building" | "live";
11	const NEXT_PHASE: Record<Phase, Phase> = { typing: "building", building: "live", live: "typing" };
12	
13	// One fixed frame height, used for every phase — previously the frame
14	// animated its own height per phase, which shifted every section below it
15	// on the page (a visible jitter). Shorter phases just center within the
16	// same fixed space now, so the page around it never moves.
17	const FRAME_HEIGHT = 620;
18	
19	const container: Variants = {
20	  hidden: {},
21	  shown: { transition: { staggerChildren: 0.11, delayChildren: 0.1 } },
22	};
23	const item: Variants = {
24	  hidden: { opacity: 0, y: 12 },
25	  shown: { opacity: 1, y: 0, transition: { duration: 0.5, ease: [0.2, 0.9, 0.2, 1] } },
26	};
27	const blockVariants: Variants = {
28	  hidden: { opacity: 0, scale: 0.85 },
29	  shown: { opacity: 1, scale: 1, transition: { duration: 0.4, ease: [0.2, 0.9, 0.2, 1] } },
30	};
31	
32	function useTypewriter(text: string, active: boolean, msPerChar: number) {
33	  const [count, setCount] = useState(0);
34	  useEffect(() => {
35	    if (!active) {
36	      setCount(0);
37	      return;
38	    }
39	    const id = setInterval(() => {
40	      setCount((c) => (c >= text.length ? c : c + 1));
41	    }, msPerChar);
42	    return () => clearInterval(id);
43	  }, [active, text, msPerChar]);
44	  return text.slice(0, count);
45	}
46	
47	function useEllipsis(active: boolean) {
48	  const [n, setN] = useState(0);
49	  useEffect(() => {
50	    if (!active) return;
51	    const id = setInterval(() => setN((v) => (v + 1) % 4), 400);
52	    return () => clearInterval(id);
53	  }, [active]);
54	  return ".".repeat(n);
55	}
56	
57	const BLOCK_STYLE = {
58	  background: "color-mix(in srgb, var(--accent) 12%, transparent)",
59	  border: "1px solid color-mix(in srgb, var(--accent) 28%, transparent)",
60	};
61	
62	// Real photography, not gradient placeholders — this is Kodely's own
63	// marketing chrome (not a customer-generated site), so it isn't bound by
64	// the no-external-requests CSP that applies to actual generated output.
65	const HERO_IMAGE = "https://picsum.photos/id/180/900/400";
66	const GALLERY_IMAGES = [
67	  "https://picsum.photos/id/685/400/400",
68	  "https://picsum.photos/id/519/400/400",
69	  "https://picsum.photos/id/704/400/400",
70	];
71	
72	const STATS = [
73	  { value: "120+", label: "Projects" },
74	  { value: "40", label: "Clients" },
75	  { value: "8 yrs", label: "Experience" },
76	];
77	
78	/** The one real hero object — a miniature browser frame that plays out the
79	 * actual product loop (type a prompt → watch it build → it's live at a real
80	 * URL) instead of showing a single static screenshot. Loops continuously;
81	 * respects prefers-reduced-motion by settling on the finished "live" frame. */
82	export function HeroMock() {
83	  const reduced = useReducedMotion();
84	  const [phase, setPhase] = useState<Phase>(reduced ? "live" : "typing");
85	  const [liveCycle, setLiveCycle] = useState(0);
86	  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
87	
88	  useEffect(() => {
89	    if (reduced) return;
90	    timeoutRef.current = setTimeout(() => {
91	      setPhase((p) => {
92	        const next = NEXT_PHASE[p];
93	        if (next === "live") setLiveCycle((c) => c + 1);
94	        return next;
95	      });
96	    }, PHASE_DURATIONS[phase]);
97	    return () => {
98	      if (timeoutRef.current) clearTimeout(timeoutRef.current);
99	    };
100	  }, [phase, reduced]);
101	
102	  const typed = useTypewriter(PROMPT_TEXT, phase === "typing", 34);
103	  const dots = useEllipsis(phase === "building");
104	
105	  return (
