import { query } from "@anthropic-ai/claude-agent-sdk";
import { existsSync, mkdirSync } from "node:fs";
import path from "node:path";

// Personal-use only. This is a standalone tool, separate from the Kodely
// product — it is never distributed, has no other users, and is not
// deployed anywhere public. It authenticates through whatever Claude login
// is active for this machine's bundled Claude Code binary (run
// `claude setup-token` once to log in with your subscription — see
// README.md), not an ANTHROPIC_API_KEY, so building with it doesn't spend
// Kodely's or anyone else's API credits.

const [, , promptArg, dirArg] = process.argv;

if (!promptArg) {
  console.error('Usage: npx tsx build-site.mts "describe the site you want" [output-dir]');
  process.exit(1);
}

const slug = promptArg
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "")
  .slice(0, 40) || "site";
const outDir = path.resolve(dirArg || path.join("sites", `${Date.now()}-${slug}`));
mkdirSync(outDir, { recursive: true });

console.log(`Building into: ${outDir}\n`);

const SYSTEM_PROMPT = `You are building a real, production-quality website — a genuine Vite + React + TypeScript + Tailwind app, not a static HTML mockup.

## First steps
If this directory is empty, scaffold it yourself: \`npm create vite@latest . -- --template react-ts\`, then install and configure Tailwind CSS (v4, CSS-first — \`@import "tailwindcss";\` in the main CSS file, no tailwind.config.js needed), then \`npm install\`. You have full Bash access — use real npm packages where they genuinely help (icons, animation, fonts via next/font-style local imports or system stacks), not just what's already installed.

## Quality bar
Ship something that looks designed, not templated. Real, specific copy for the subject at hand — never "Lorem ipsum" and never placeholder headings like "Your Title Here". Responsive down to 380px. Semantic HTML, labelled form controls, sufficient colour contrast, a visible :focus style. Include a dark-mode treatment unless the brief implies otherwise. Give the page one distinctive visual idea rather than a generic hero-plus-three-cards. Real images are fine to reference from a CDN (unsplash.com/photos, picsum.photos) since this runs locally, not inside a sandboxed CSP.

## Working style
Build real, composable React components — a Hero, a FeatureGrid, a Footer — not one giant App.tsx. After scaffolding and building the requested site, run \`npm run build\` to confirm it compiles cleanly, fixing anything that fails. Finish by telling the user how to preview it (\`npm run dev\`).`;

for await (const message of query({
  prompt: promptArg,
  options: {
    cwd: outDir,
    systemPrompt: SYSTEM_PROMPT,
    allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
    permissionMode: "acceptEdits",
  },
})) {
  if (message.type === "assistant" && message.message?.content) {
    for (const block of message.message.content) {
      if ("text" in block && block.text) {
        process.stdout.write(block.text);
      } else if ("name" in block) {
        console.log(`\n[tool] ${block.name}`);
      }
    }
  } else if (message.type === "result") {
    console.log(`\n\nDone: ${message.subtype}`);
    if ("total_cost_usd" in message && message.total_cost_usd) {
      console.log(`(Charged to your Claude subscription's usage, not an API key — no Kodely credits involved.)`);
    }
    console.log(`\nProject is in: ${outDir}`);
    console.log(`cd ${outDir} && npm run dev`);
  }
}

