import { query } from "@anthropic-ai/claude-agent-sdk";
import { readFileSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const ROOT = path.resolve(__dirname, "..");
export const SITES_DIR = path.join(ROOT, "sites");

// The skill file is the single evolving source of truth for build quality —
// refine SKILL.md as patterns emerge across builds; every future build
// (CLI or web UI) picks up the change immediately, no code change needed.
function loadHouseStyle(): string {
  const skillPath = path.join(ROOT, "skills/kodely-house-style/SKILL.md");
  const raw = readFileSync(skillPath, "utf8");
  // Strip the YAML frontmatter (--- ... ---), keep the body as the prompt.
  return raw.replace(/^---\n[\s\S]*?\n---\n/, "").trim();
}

export function slugify(prompt: string): string {
  return (
    prompt
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 40) || "site"
  );
}

export type BuildMeta = {
  id: string;
  prompt: string;
  createdAt: string;
  status: "running" | "done" | "error";
};

export function listSites(): BuildMeta[] {
  if (!existsSync(SITES_DIR)) return [];
  const { readdirSync } = require("node:fs") as typeof import("node:fs");
  return readdirSync(SITES_DIR)
    .filter((name) => existsSync(path.join(SITES_DIR, name, "meta.json")))
    .map((name) => JSON.parse(readFileSync(path.join(SITES_DIR, name, "meta.json"), "utf8")))
    .sort((a: BuildMeta, b: BuildMeta) => b.createdAt.localeCompare(a.createdAt));
}

function writeMeta(id: string, meta: BuildMeta) {
  writeFileSync(path.join(SITES_DIR, id, "meta.json"), JSON.stringify(meta, null, 2));
}

/** Runs one build, yielding plain-text progress lines as it goes — shared
 * by both the CLI script and the web UI's SSE stream. */
export async function* runBuild(prompt: string, id?: string): AsyncGenerator<string> {
  const buildId = id ?? `${Date.now()}-${slugify(prompt)}`;
  const outDir = path.join(SITES_DIR, buildId);
  mkdirSync(outDir, { recursive: true });

  const meta: BuildMeta = { id: buildId, prompt, createdAt: new Date().toISOString(), status: "running" };
  writeMeta(buildId, meta);
  yield `Building into: ${outDir}\n`;

  try {
    for await (const message of query({
      prompt,
      options: {
        cwd: outDir,
        systemPrompt: loadHouseStyle(),
        allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
        permissionMode: "acceptEdits",
      },
    })) {
      if (message.type === "assistant" && message.message?.content) {
        for (const block of message.message.content) {
          if ("text" in block && block.text) yield block.text;
          else if ("name" in block) yield `\n[tool] ${block.name}\n`;
        }
      } else if (message.type === "result") {
        yield `\n\nDone: ${message.subtype}\n`;
        meta.status = message.subtype === "success" ? "done" : "error";
        writeMeta(buildId, meta);
      }
    }
  } catch (err) {
    meta.status = "error";
    writeMeta(buildId, meta);
    yield `\n\nError: ${err instanceof Error ? err.message : String(err)}\n`;
  }
}

