import { query } from "@anthropic-ai/claude-agent-sdk";
import { mkdtemp, mkdir, writeFile, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import fg from "fast-glob";

export type AgentEvent =
  | { type: "status"; text: string }
  | { type: "text"; text: string }
  | { type: "file"; path: string; action: "write" | "delete" }
  | {
      type: "usage";
      model: string;
      inputTokens: number;
      outputTokens: number;
      cacheReadTokens: number;
      cacheWriteTokens: number;
    };

export type FileMap = Record<string, string>;

// PERSONAL INSTANCE — generation runs through the Claude Agent SDK,
// authenticated via this machine's `claude setup-token` subscription login
// (see README-personal.md), not ANTHROPIC_API_KEY. No per-generation API
// cost, so every usage event below is reported as zero — there is nothing
// to meter. This file is the one deliberate divergence from the real
// Kodely product's lib/agent.ts; everything else (route.ts, credits.ts,
// the UI) is untouched, so the external contract below must stay identical
// to the real file's, or the rest of the app breaks.
//
// The system prompt is loaded from skills/kodely-house-style/SKILL.md
// instead of being hardcoded, so refining it during the testing period —
// the whole point of this instance — takes effect immediately on the next
// build, and the same file is the thing you port back into the real
// product's lib/agent.ts SYSTEM constant once a change proves out.

async function loadHouseStyle(): Promise<string> {
  const skillPath = path.join(process.cwd(), "skills/kodely-house-style/SKILL.md");
  const raw = await readFile(skillPath, "utf8");
  return raw.replace(/^---\n[\s\S]*?\n---\n/, "").trim();
}

/** Reject path traversal and absolute paths before anything touches the DB. */
export function normalizePath(raw: string): string | null {
  const p = raw.trim().replace(/^\.?\//, "");
  if (!p || p.length > 200) return null;
  if (p.includes("..") || p.startsWith("/") || p.includes("\\")) return null;
  if (!/^[A-Za-z0-9._/-]+$/.test(p)) return null;
  return p;
}

async function writeFileMap(dir: string, files: FileMap) {
  for (const [rel, content] of Object.entries(files)) {
    const full = path.join(dir, rel);
    await mkdir(path.dirname(full), { recursive: true });
    await writeFile(full, content, "utf8");
  }
}

async function readFileTree(dir: string): Promise<FileMap> {
  const paths = await fg("**/*", { cwd: dir, dot: false, onlyFiles: true, ignore: ["node_modules/**", ".git/**"] });
  const out: FileMap = {};
  for (const rel of paths) {
    out[rel] = await readFile(path.join(dir, rel), "utf8");
  }
  return out;
}

type RunOptions = {
  history: { role: "user" | "assistant"; content: string }[];
  request: string;
  files: FileMap;
  kind: "create" | "edit";
  image?: { mediaType: string; data: string };
  onWrite: (path: string, content: string) => Promise<boolean>;
  onDelete: (path: string) => Promise<boolean>;
  signal?: AbortSignal;
};

export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
  const workDir = await mkdtemp(path.join(tmpdir(), "kodely-personal-"));

  try {
    await writeFileMap(workDir, opts.files);

    let imageNote = "";
    if (opts.image) {
      const ext = opts.image.mediaType.split("/")[1] ?? "png";
      const imgPath = path.join(workDir, `.reference.${ext}`);
      await writeFile(imgPath, Buffer.from(opts.image.data, "base64"));
      imageNote = `\n\nA reference image was attached to this request — Read the file .reference.${ext} in this directory to see it, then use it as visual/style guidance.`;
    }

    const historyText = opts.history.length
      ? `## Prior conversation on this project\n${opts.history
          .map((h) => `${h.role === "user" ? "User" : "You"}: ${h.content}`)
          .join("\n\n")}\n\n`
      : "";

    const prompt = `${historyText}## Current request\n${opts.request}${imageNote}`;

    const systemPrompt = await loadHouseStyle();

    yield { type: "status", text: opts.kind === "create" ? "Building your site…" : "Applying your changes…" };

    for await (const message of query({
      prompt,
      options: {
        cwd: workDir,
        systemPrompt,
        allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
        permissionMode: "acceptEdits",
      },
    })) {
      if (opts.signal?.aborted) break;

      if (message.type === "assistant" && message.message?.content) {
        for (const block of message.message.content) {
          if ("text" in block && block.text) yield { type: "text", text: block.text };
        }
      } else if (message.type === "result") {
        // Subscription-billed — nothing to meter, so usage is reported as
        // zero rather than guessed. credits.ts computes 0 credits from this
        // regardless of the `model` string, so every personal build is free.
        yield {
          type: "usage",
          model: "claude-agent-sdk-personal",
          inputTokens: 0,
          outputTokens: 0,
          cacheReadTokens: 0,
          cacheWriteTokens: 0,
        };
      }
    }

    if (opts.signal?.aborted) return;

    const after = await readFileTree(workDir);

    for (const [p, content] of Object.entries(after)) {
      const normalized = normalizePath(p);
      if (!normalized) continue;
      if (opts.files[p] === content) continue; // unchanged
      const ok = await opts.onWrite(normalized, content);
      if (ok) yield { type: "file", path: normalized, action: "write" };
    }
    for (const p of Object.keys(opts.files)) {
      if (p in after) continue;
      const normalized = normalizePath(p);
      if (!normalized) continue;
      const ok = await opts.onDelete(normalized);
      if (ok) yield { type: "file", path: normalized, action: "delete" };
    }
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}

