import { randomUUID } from "node:crypto";
import db from "./db";

const COLUMNS = ["Backlog", "In Progress", "Blocked", "Done"];

// The Phase A/B/C/D roadmap synthesized from the full Nxeon Kodely board
// audit (2026-08-20) — seeded here as a starting point, not a mirror of
// that board. This one is yours to reshape as you actually work.
const SEED_CARDS: { title: string; description: string; phase: "A" | "B" | "C" | "D" }[] = [
  { phase: "A", title: "Off-site backups + disaster recovery", description: "No off-site snapshot, no defined RTO/RPO, no restore drill. Flagged repeatedly, still nothing built." },
  { phase: "A", title: "Anthropic multi-key pool + spend caps", description: "Single key, no pool, no failover, no hard spend ceiling. Already caused one real cost scare." },
  { phase: "A", title: "Service-key rotation runbook", description: "Two live keys already pasted in plaintext once. Need a standing rotation process, not a one-off fix." },
  { phase: "A", title: "Kodely tier numbers — names, prices, credits", description: "Pricing model is decided; the actual sellable tiers aren't. Stripe is wired and inert waiting on this." },
  { phase: "A", title: "Pre-GA security review", description: "No pen test or formal review of the build/publish path yet." },

  { phase: "B", title: "Click-to-edit visual editing", description: "Chat editing works; clicking an element to edit it directly doesn't exist yet." },
  { phase: "B", title: "Asset / image upload", description: "No way for a user to upload their own logo or photos onto a generated site." },
  { phase: "B", title: "Diff-based edits, not full-file rewrites", description: "Every edit regenerates whole files — the biggest remaining cost lever." },
  { phase: "B", title: "Plan-before-spend / cost estimate", description: "No estimate shown before an expensive build starts." },
  { phase: "B", title: "Auto-SEO on generated output", description: "Generated sites ship with no meta tags, sitemap, or OG image." },
  { phase: "B", title: "Basic content moderation", description: "Rate limits exist; no check for phishing/brand-clone/abusive content on publish." },

  { phase: "C", title: "Real admin panel", description: "Only a read-only cost dashboard exists. No funnel, revenue, or user management view." },
  { phase: "C", title: "195 remaining SEO posts", description: "56 of 251 briefs are live." },
  { phase: "C", title: "Billing UX completion", description: "Waits on the Phase A tier-numbers decision and real Stripe keys." },
  { phase: "C", title: "\"Built with Kodely\" badge + referral", description: "The cheapest growth loop on the roadmap, still uncarded into anything buildable." },

  { phase: "D", title: "Backend generation — DB, auth, payments", description: "The actual \"live business\" promise. Needs DB-per-project isolation + a hardened sandbox first." },
  { phase: "D", title: "Custom domains via Nxeon", description: "The natural monetization fence every competitor gates behind a paid tier." },
  { phase: "D", title: "Firecracker sandbox isolation", description: "Deferred while output is frontend-only — mandatory once backend code execution starts." },
  { phase: "D", title: "Agency / white-label, teams, marketplace", description: "Proven revenue models in this category, downstream of product-market fit." },
];

export function ensureSeeded() {
  const count = (db.prepare("SELECT COUNT(*) as n FROM columns").get() as { n: number }).n;
  if (count > 0) return;

  const colIds: Record<string, string> = {};
  COLUMNS.forEach((name, i) => {
    const id = randomUUID();
    colIds[name] = id;
    db.prepare("INSERT INTO columns (id, name, position) VALUES (?, ?, ?)").run(id, name, i);
  });

  SEED_CARDS.forEach((c, i) => {
    db.prepare(
      "INSERT INTO cards (id, columnId, title, description, phase, position) VALUES (?, ?, ?, ?, ?, ?)",
    ).run(randomUUID(), colIds["Backlog"], c.title, c.description, c.phase, i);
  });
}

