import { randomUUID } from "node:crypto";
import db from "@/lib/db";
import { ensureSeeded } from "@/lib/seed";

export async function GET() {
  ensureSeeded();
  const columns = db.prepare("SELECT * FROM columns ORDER BY position").all();
  const cards = db.prepare("SELECT * FROM cards ORDER BY position").all();
  return Response.json({ columns, cards });
}

export async function POST(req: Request) {
  const body = (await req.json()) as { columnId?: string; title?: string };
  const title = body.title?.trim();
  if (!title || !body.columnId) {
    return Response.json({ error: "Missing title or columnId." }, { status: 400 });
  }
  const max = db
    .prepare("SELECT COALESCE(MAX(position), -1) as m FROM cards WHERE columnId = ?")
    .get(body.columnId) as { m: number };
  const id = randomUUID();
  db.prepare(
    "INSERT INTO cards (id, columnId, title, description, phase, position) VALUES (?, ?, ?, '', NULL, ?)",
  ).run(id, body.columnId, title, max.m + 1);
  const card = db.prepare("SELECT * FROM cards WHERE id = ?").get(id);
  return Response.json({ card });
}

