import db from "@/lib/db";

export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const body = (await req.json()) as { columnId?: string; position?: number; title?: string; description?: string };

  if (body.columnId !== undefined && body.position !== undefined) {
    db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?").run(body.columnId, body.position, id);
  }
  if (body.title !== undefined) {
    db.prepare("UPDATE cards SET title = ? WHERE id = ?").run(body.title, id);
  }
  if (body.description !== undefined) {
    db.prepare("UPDATE cards SET description = ? WHERE id = ?").run(body.description, id);
  }
  const card = db.prepare("SELECT * FROM cards WHERE id = ?").get(id);
  return Response.json({ card });
}

export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  db.prepare("DELETE FROM cards WHERE id = ?").run(id);
  return Response.json({ ok: true });
}

