import { ensureSeeded } from "@/lib/seed";

export async function GET() {
  ensureSeeded();
  const boards = db.prepare("SELECT * FROM boards ORDER BY position").all();
  return Response.json({ boards });
}

export async function POST(req: Request) {
  const body = (await req.json()) as { name?: string };
  const name = body.name?.trim();
  if (!name) return Response.json({ error: "Missing name." }, { status: 400 });
  const max = db.prepare("SELECT COALESCE(MAX(position), -1) as m FROM boards").get() as { m: number };
  const id = randomUUID();
  db.prepare("INSERT INTO boards (id, name, position) VALUES (?, ?, ?)").run(id, name, max.m + 1);
  const board = db.prepare("SELECT * FROM boards WHERE id = ?").get(id);
  return Response.json({ board });
}

