import db from "@/lib/db";

export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const body = (await req.json()) as {
    columnId?: string;
    position?: number;
    title?: string;
    description?: string;
    type?: string;
    priority?: string;
    labels?: string[];
    assignee?: string | null;
    archived?: boolean;
  };

  if (body.columnId !== undefined && body.position !== undefined) {
    db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?").run(body.columnId, body.position, id);
  }
  if (body.title !== undefined) db.prepare("UPDATE cards SET title = ? WHERE id = ?").run(body.title, id);
  if (body.description !== undefined) db.prepare("UPDATE cards SET description = ? WHERE id = ?").run(body.description, id);
  if (body.type !== undefined) db.prepare("UPDATE cards SET type = ? WHERE id = ?").run(body.type, id);
  if (body.priority !== undefined) db.prepare("UPDATE cards SET priority = ? WHERE id = ?").run(body.priority, id);
  if (body.labels !== undefined) db.prepare("UPDATE cards SET labels = ? WHERE id = ?").run(JSON.stringify(body.labels), id);
  if (body.assignee !== undefined) db.prepare("UPDATE cards SET assignee = ? WHERE id = ?").run(body.assignee, id);
  if (body.archived !== undefined) {
    db.prepare("UPDATE cards SET archivedAt = ? WHERE id = ?").run(body.archived ? new Date().toISOString() : null, id);
  }

  const card = db.prepare("SELECT * FROM cards WHERE id = ?").get(id);
  return Response.json({ card });
}

export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  db.prepare("DELETE FROM cards WHERE id = ?").run(id);
  return Response.json({ ok: true });
}

