import { randomUUID } from "node:crypto";
import db from "@/lib/db";
import { ensureSeeded } from "@/lib/seed";

export async function GET(req: Request) {
  ensureSeeded();
  const { searchParams } = new URL(req.url);
  let boardId = searchParams.get("boardId");
  if (!boardId) {
    boardId = (db.prepare("SELECT id FROM boards ORDER BY position LIMIT 1").get() as { id: string } | undefined)?.id ?? null;
  }
  if (!boardId) return Response.json({ columns: [], cards: [] });

  const columns = db.prepare("SELECT * FROM columns WHERE boardId = ? ORDER BY position").all(boardId);
  const columnIds = (columns as { id: string }[]).map((c) => c.id);
  const cards = columnIds.length
    ? db
        .prepare(
          `SELECT c.*,
            (SELECT COUNT(*) FROM attachments a WHERE a.cardId = c.id) as attachmentCount,
            (SELECT COUNT(*) FROM comments cm WHERE cm.cardId = c.id) as commentCount
           FROM cards c WHERE c.columnId IN (${columnIds.map(() => "?").join(",")}) ORDER BY c.position`,
        )
        .all(...columnIds)
    : [];
  return Response.json({ columns, cards });
}

export async function POST(req: Request) {
  const body = (await req.json()) as { columnId?: string; title?: string };
  const title = body.title?.trim();
  if (!title || !body.columnId) {
    return Response.json({ error: "Missing title or columnId." }, { status: 400 });
  }
  const max = db
    .prepare("SELECT COALESCE(MAX(position), -1) as m FROM cards WHERE columnId = ?")
    .get(body.columnId) as { m: number };
  const id = randomUUID();
  db.prepare(
    "INSERT INTO cards (id, columnId, title, description, phase, position) VALUES (?, ?, ?, '', NULL, ?)",
  ).run(id, body.columnId, title, max.m + 1);
  const card = db.prepare("SELECT * FROM cards WHERE id = ?").get(id);
  return Response.json({ card });
}

