import { randomUUID } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import db from "@/lib/db";

const UPLOAD_ROOT = path.join(process.cwd(), "uploads");

function kindFromMime(mime: string): string {
  if (mime.startsWith("image/")) return "IMAGE";
  if (mime.startsWith("video/")) return "VIDEO";
  return "FILE";
}

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const attachments = db
    .prepare("SELECT id, cardId, filename, mime, sizeBytes, kind, createdAt FROM attachments WHERE cardId = ? ORDER BY createdAt")
    .all(id);
  return Response.json({ attachments });
}

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const body = (await req.json()) as { filename?: string; mime?: string; dataBase64?: string };
  if (!body.filename || !body.dataBase64) {
    return Response.json({ error: "Missing filename or dataBase64." }, { status: 400 });
  }

  const mime = body.mime || "application/octet-stream";
  const buffer = Buffer.from(body.dataBase64, "base64");
  const attachmentId = randomUUID();
  const ext = path.extname(body.filename) || "";
  const storedName = `${attachmentId}${ext}`;

  const cardDir = path.join(UPLOAD_ROOT, id);
  await mkdir(cardDir, { recursive: true });
  await writeFile(path.join(cardDir, storedName), buffer);

  db.prepare(
    "INSERT INTO attachments (id, cardId, filename, storedName, mime, sizeBytes, kind) VALUES (?, ?, ?, ?, ?, ?, ?)",
  ).run(attachmentId, id, body.filename, storedName, mime, buffer.length, kindFromMime(mime));

  const attachment = db.prepare("SELECT id, cardId, filename, mime, sizeBytes, kind, createdAt FROM attachments WHERE id = ?").get(attachmentId);
  return Response.json({ attachment });
}

