import { readFile, rm } from "node:fs/promises";
import path from "node:path";
import db from "@/lib/db";

const UPLOAD_ROOT = path.join(process.cwd(), "uploads");

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const row = db
    .prepare("SELECT cardId, filename, storedName, mime FROM attachments WHERE id = ?")
    .get(id) as { cardId: string; filename: string; storedName: string; mime: string } | undefined;
  if (!row) return new Response("Not found", { status: 404 });

  const filePath = path.join(UPLOAD_ROOT, row.cardId, row.storedName);
  const data = await readFile(filePath);
  return new Response(new Uint8Array(data), {
    headers: {
      "Content-Type": row.mime,
      "Content-Disposition": `inline; filename="${encodeURIComponent(row.filename)}"`,
    },
  });
}

export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const row = db
    .prepare("SELECT cardId, storedName FROM attachments WHERE id = ?")
    .get(id) as { cardId: string; storedName: string } | undefined;
  if (row) {
    await rm(path.join(UPLOAD_ROOT, row.cardId, row.storedName), { force: true });
  }
  db.prepare("DELETE FROM attachments WHERE id = ?").run(id);
  return Response.json({ ok: true });
}

