  BUG: "var(--phase-a)",
  CHORE: "var(--faint)",
};

const PRIORITY_COLOR: Record<CardPriority, string> = {
  LOW: "var(--faint)",
  NORMAL: "var(--ink-2)",
  HIGH: "var(--phase-b)",
  URGENT: "var(--phase-a)",
};

function fmtSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(",")[1] ?? "");
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export function CardModal({
  card,
  onClose,
  onUpdate,
  onDelete,
}: {
  card: Card;
  onClose: () => void;
  onUpdate: (patch: Partial<Card> & { id: string }) => void;
  onDelete: (id: string) => void;
}) {
  const [title, setTitle] = useState(card.title);
  const [description, setDescription] = useState(card.description);
  const [editingDescription, setEditingDescription] = useState(!card.description);
  const [labelInput, setLabelInput] = useState("");
  const [labels, setLabels] = useState<string[]>(parseLabels(card.labels));
  const [assignee, setAssignee] = useState(card.assignee ?? "");
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState("");
  const [uploading, setUploading] = useState(false);
  const dropRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetch(`/api/cards/${card.id}/attachments`)
      .then((r) => r.json())
      .then((d) => setAttachments(d.attachments ?? []));
    fetch(`/api/cards/${card.id}/comments`)
      .then((r) => r.json())
      .then((d) => setComments(d.comments ?? []));
  }, [card.id]);

  function saveTitle() {
    const t = title.trim();
    if (t && t !== card.title) onUpdate({ id: card.id, title: t });
  }

  function saveDescription() {
    if (description !== card.description) onUpdate({ id: card.id, description });
    setEditingDescription(false);
  }

  function commitLabels(next: string[]) {
    setLabels(next);
    onUpdate({ id: card.id, labels: JSON.stringify(next) as unknown as string });
  }

  function addLabel() {
    const l = labelInput.trim();
    if (!l || labels.includes(l)) {
      setLabelInput("");
      return;
    }
    commitLabels([...labels, l]);
    setLabelInput("");
  }

  function removeLabel(l: string) {
    commitLabels(labels.filter((x) => x !== l));
  }

  async function uploadFiles(files: FileList | File[]) {
    setUploading(true);
    try {
      for (const file of Array.from(files)) {
        const dataBase64 = await fileToBase64(file);
        const res = await fetch(`/api/cards/${card.id}/attachments`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ filename: file.name, mime: file.type, dataBase64 }),
        });
        const { attachment } = await res.json();
        if (attachment) setAttachments((a) => [...a, attachment]);
      }
    } finally {
      setUploading(false);
    }
  }

  async function deleteAttachment(id: string) {
    setAttachments((a) => a.filter((x) => x.id !== id));
    await fetch(`/api/attachments/${id}`, { method: "DELETE" });
  }

  async function postComment() {
    const body = newComment.trim();
    if (!body) return;
    setNewComment("");
    const res = await fetch(`/api/cards/${card.id}/comments`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ body }),
    });
    const { comment } = await res.json();
    if (comment) setComments((c) => [...c, comment]);
  }

  async function deleteComment(id: string) {
    setComments((c) => c.filter((x) => x.id !== id));
    await fetch(`/api/comments/${id}`, { method: "DELETE" });
  }

  const onPaste = useCallback(
    (e: ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      const files: File[] = [];
      for (const item of Array.from(items)) {
        if (item.kind === "file") {
          const f = item.getAsFile();
          if (f) files.push(f);
        }
      }
      if (files.length) {
        e.preventDefault();
        uploadFiles(files);
      }
    },
    [card.id],
  );

  useEffect(() => {
    document.addEventListener("paste", onPaste);
    return () => document.removeEventListener("paste", onPaste);
  }, [onPaste]);

  const html = editingDescription ? "" : (marked.parse(description || "*No description yet.*") as string);

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto p-4 py-10 sm:p-8"
      style={{ background: "color-mix(in srgb, #000 55%, transparent)" }}
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-2xl rounded-2xl border p-6"
        style={{ borderColor: "var(--line)", background: "var(--panel)", boxShadow: "var(--sh-s)" }}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="flex flex-1 items-center gap-2">
            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={saveTitle}
              onKeyDown={(e) => {
                if (e.key === "Enter") (e.target as HTMLInputElement).blur();
              }}
              className="w-full rounded-lg bg-transparent px-1 py-1 text-lg font-semibold outline-none"
            />
            <MicButton value={title} onChange={setTitle} />
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="shrink-0 rounded-md p-1 text-[var(--faint)] hover:text-[var(--foreground)]"
          >
            ✕
          </button>
        </div>

        <div className="mt-4 flex flex-wrap items-center gap-2">
          <select
            value={card.type}
            onChange={(e) => onUpdate({ id: card.id, type: e.target.value as CardType })}
            className="rounded-md border bg-transparent px-2 py-1 text-xs font-medium outline-none"
            style={{ borderColor: "var(--line)", color: TYPE_COLOR[card.type] }}
          >
            {CARD_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
          <select
            value={card.priority}
            onChange={(e) => onUpdate({ id: card.id, priority: e.target.value as CardPriority })}
            className="rounded-md border bg-transparent px-2 py-1 text-xs font-medium outline-none"
            style={{ borderColor: "var(--line)", color: PRIORITY_COLOR[card.priority] }}
          >
            {CARD_PRIORITIES.map((p) => (
              <option key={p} value={p}>
                {p}
              </option>
            ))}
          </select>
          <input
            value={assignee}
            onChange={(e) => setAssignee(e.target.value)}
            onBlur={() => onUpdate({ id: card.id, assignee: assignee || null })}
            placeholder="Unassigned"
            className="w-32 rounded-md border bg-transparent px-2 py-1 text-xs outline-none placeholder:text-[var(--faint)]"
            style={{ borderColor: "var(--line)" }}
          />
          <button
            onClick={() => onUpdate({ id: card.id, archivedAt: card.archivedAt ? null : new Date().toISOString() } as any)}
            className="rounded-md border px-2 py-1 text-xs font-medium"
            style={{ borderColor: "var(--line)", color: card.archivedAt ? "var(--accent)" : "var(--ink-2)" }}
          >
            {card.archivedAt ? "Unarchive" : "Archive"}
          </button>
          <button
            onClick={() => onDelete(card.id)}
            className="ml-auto rounded-md px-2 py-1 text-xs font-medium text-[var(--faint)] hover:text-[var(--phase-a)]"
          >
            Delete card
          </button>
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-1.5">
          {labels.map((l) => (
            <span
              key={l}
              className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium"
              style={{ background: "color-mix(in srgb, var(--accent) 12%, transparent)", color: "var(--accent)" }}
            >
              {l}
              <button onClick={() => removeLabel(l)} aria-label={`Remove ${l}`} className="opacity-60 hover:opacity-100">
                ×
              </button>
            </span>
          ))}
          <input
            value={labelInput}
            onChange={(e) => setLabelInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                addLabel();
              }
            }}
            onBlur={addLabel}
            placeholder="+ label"
            className="w-20 rounded-md border-none bg-transparent px-1 py-0.5 text-[11px] outline-none placeholder:text-[var(--faint)]"
          />
        </div>

        <div className="mt-5">
          <div className="mb-1.5 flex items-center justify-between">
            <p className="font-mono text-[10px] font-medium uppercase tracking-wide text-[var(--faint)]">
              Description
            </p>
            <div className="flex items-center gap-1">
              {!editingDescription && <MicButton value={description} onChange={setDescription} />}
              <button
                onClick={() => (editingDescription ? saveDescription() : setEditingDescription(true))}
                className="text-[11px] font-medium text-[var(--accent)]"
              >
                {editingDescription ? "Save" : "Edit"}
              </button>
            </div>
          </div>
          {editingDescription ? (
            <div className="flex items-start gap-1.5">
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={5}
                placeholder="Markdown supported…"
                className="w-full resize-y rounded-lg border bg-transparent px-3 py-2 text-sm outline-none placeholder:text-[var(--faint)]"
                style={{ borderColor: "var(--line)" }}
              />
            </div>
          ) : (
            <div
              className="prose-sm max-w-none rounded-lg border px-3 py-2 text-sm leading-relaxed text-[var(--ink-2)] [&_a]:text-[var(--accent)] [&_code]:rounded [&_code]:bg-[var(--line-2)] [&_code]:px-1 [&_p]:my-1.5 [&_ul]:my-1.5 [&_ul]:list-disc [&_ul]:pl-5"
              style={{ borderColor: "var(--line)" }}
              dangerouslySetInnerHTML={{ __html: html }}
            />
          )}
        </div>

        <div className="mt-5">
          <p className="mb-1.5 font-mono text-[10px] font-medium uppercase tracking-wide text-[var(--faint)]">
            Attachments
          </p>
          <div
            ref={dropRef}
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => {
              e.preventDefault();
              if (e.dataTransfer.files.length) uploadFiles(e.dataTransfer.files);
            }}
            className="flex flex-wrap gap-2 rounded-lg border border-dashed p-3"
            style={{ borderColor: "var(--line)" }}
          >
            {attachments.map((a) => (
              <div
                key={a.id}
                className="group relative flex w-24 flex-col items-center gap-1 rounded-lg border p-2 text-center"
                style={{ borderColor: "var(--line)", background: "var(--background)" }}
              >
                {a.kind === "IMAGE" ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={`/api/attachments/${a.id}`} alt={a.filename} className="h-14 w-full rounded object-cover" />
                ) : a.kind === "VIDEO" ? (
                  <video src={`/api/attachments/${a.id}`} className="h-14 w-full rounded object-cover" muted />
                ) : (
                  <div className="flex h-14 w-full items-center justify-center rounded text-2xl">📄</div>
                )}
                <a
                  href={`/api/attachments/${a.id}`}
                  target="_blank"
                  rel="noreferrer"
                  className="w-full truncate text-[10px] text-[var(--ink-2)]"
                  title={a.filename}
                >
                  {a.filename}
                </a>
                <span className="text-[9px] text-[var(--faint)]">{fmtSize(a.sizeBytes)}</span>
                <button
                  onClick={() => deleteAttachment(a.id)}
                  aria-label={`Delete ${a.filename}`}
                  className="absolute -right-1.5 -top-1.5 hidden h-5 w-5 items-center justify-center rounded-full text-xs group-hover:flex"
                  style={{ background: "var(--panel)", border: "1px solid var(--line)", color: "var(--faint)" }}
                >
                  ×
                </button>
              </div>
            ))}
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className="flex w-24 flex-col items-center justify-center gap-1 rounded-lg border border-dashed p-2 text-[11px] text-[var(--faint)] hover:text-[var(--accent)]"
              style={{ borderColor: "var(--line)" }}
            >
              {uploading ? "Uploading…" : "+ Add file"}
            </button>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              className="hidden"
              onChange={(e) => {
                if (e.target.files?.length) uploadFiles(e.target.files);
                e.target.value = "";
              }}
            />
          </div>
          <p className="mt-1 text-[10px] text-[var(--faint)]">
            Drag files in, paste (Ctrl/Cmd+V) an image or clip anywhere on this card, or use + Add file.
          </p>
        </div>

        <div className="mt-5">
          <p className="mb-1.5 font-mono text-[10px] font-medium uppercase tracking-wide text-[var(--faint)]">
            Comments
          </p>
          <div className="flex flex-col gap-2">
            {comments.map((c) => (
              <div
                key={c.id}
                className="group flex items-start justify-between gap-2 rounded-lg border px-3 py-2"
                style={{ borderColor: "var(--line)" }}
              >
                <p className="text-sm text-[var(--ink-2)]">{c.body}</p>
                <button
                  onClick={() => deleteComment(c.id)}
                  className="shrink-0 text-[var(--faint)] opacity-0 group-hover:opacity-100 hover:text-[var(--phase-a)]"
                  aria-label="Delete comment"
                >
                  ×
                </button>
              </div>
            ))}
          </div>
          <div className="mt-2 flex items-center gap-1.5">
            <input
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") postComment();
              }}
              placeholder="Add a comment…"
              className="w-full rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
              style={{ borderColor: "var(--line)" }}
            />
            <MicButton value={newComment} onChange={setNewComment} />
          </div>
        </div>
      </div>
    </div>
  );
}

