// One-off import: pulls the full Kodely board (705 cards, 28 columns) from
// the real Nxeon Postgres DB and inserts it into this local SQLite board app
// as a new "Kodely Research" board, preserving columns/labels/type/priority/
// assignee. Run from /root/kodely-board with: node scripts/import-kodely-board.mjs
import { randomUUID } from "node:crypto";
import path from "node:path";
import Database from "better-sqlite3";
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/index.js";

const KODELY_BOARD_ID = "cmsw33mv20000hlokqv7gze6u";
const NEW_BOARD_NAME = "Kodely Research";

const sqlite = new Database(path.join(process.cwd(), "board.sqlite"));
sqlite.pragma("journal_mode = WAL");

const prisma = new PrismaClient();

async function main() {
  const existing = sqlite.prepare("SELECT id FROM boards WHERE name = ?").get(NEW_BOARD_NAME);
  if (existing) {
    console.log(`"${NEW_BOARD_NAME}" already exists (${existing.id}) — skipping import.`);
    await prisma.$disconnect();
    return;
  }

  const columns = await prisma.boardColumn.findMany({
    where: { boardId: KODELY_BOARD_ID },
    orderBy: { position: "asc" },
  });
  const cards = await prisma.card.findMany({
    where: { boardId: KODELY_BOARD_ID },
    orderBy: { position: "asc" },
  });

  console.log(`Fetched ${columns.length} columns, ${cards.length} cards from the real Kodely board.`);

  const maxBoardPos = sqlite.prepare("SELECT COALESCE(MAX(position), -1) as m FROM boards").get().m;
  const boardId = randomUUID();
  sqlite.prepare("INSERT INTO boards (id, name, position) VALUES (?, ?, ?)").run(boardId, NEW_BOARD_NAME, maxBoardPos + 1);

  const colIdMap = new Map();
  const insertColumn = sqlite.prepare("INSERT INTO columns (id, boardId, name, position) VALUES (?, ?, ?, ?)");
  for (const col of columns) {
    const localId = randomUUID();
    colIdMap.set(col.id, localId);
    insertColumn.run(localId, boardId, col.name, col.position);
  }

  const insertCard = sqlite.prepare(
    `INSERT INTO cards (id, columnId, title, description, phase, type, priority, labels, assignee, position, archivedAt, createdAt)
     VALUES (?, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?)`,
  );

  let skipped = 0;
  const insertMany = sqlite.transaction((rows) => {
    for (const c of rows) {
      const localColumnId = colIdMap.get(c.columnId);
      if (!localColumnId) {
        skipped++;
        continue;
      }
      insertCard.run(
        randomUUID(),
        localColumnId,
        c.title,
        c.description ?? "",
        c.type,
        c.priority,
        JSON.stringify(c.labels ?? []),
        c.assignee ?? null,
        c.position,
        c.archivedAt ? c.archivedAt.toISOString() : null,
        c.createdAt.toISOString(),
      );
    }
  });
  insertMany(cards);

  console.log(`Imported ${cards.length - skipped} cards into "${NEW_BOARD_NAME}" (${boardId}).`);
  if (skipped) console.log(`Skipped ${skipped} cards with no matching column.`);

  await prisma.$disconnect();
}

main().catch(async (err) => {
  console.error(err);
  await prisma.$disconnect();
  process.exit(1);
});

